# Optional OpenColorIO binding. The ACES CG config used by default is built into OCIO 2.5+.
try:
    import PyOpenColorIO as _OCIO  # noqa: E402
    HAVE_OCIO = True
    _OCIO_IMPORT_ERROR = ""
except Exception as _ocio_import_exc:  # pragma: no cover - optional runtime dependency
    _OCIO = None
    HAVE_OCIO = False
    _OCIO_IMPORT_ERROR = f"{type(_ocio_import_exc).__name__}: {_ocio_import_exc}"

OCIO_DEFAULT_CONFIG = "ocio://cg-config-v4.0.0_aces-v2.0_ocio-v2.5"
OCIO_UNAVAILABLE_LABEL = "OpenColorIO unavailable — install opencolorio"
_OCIO_CONFIG_CACHE = {}
_LAST_OCIO_ERROR = ""
_OCIO_CONFIG_CACHE_LOCK = threading.RLock()
_OCIO_PROCESSOR_CACHE = {}
_OCIO_PROCESSOR_CACHE_LOCK = threading.RLock()


def _ocio_version_text() -> str:
    """Return the loaded PyOpenColorIO version without assuming a specific API build."""
    if not HAVE_OCIO or _OCIO is None:
        return "not installed"
    try:
        get_version = getattr(_OCIO, "GetVersion", None)
        if callable(get_version):
            return str(get_version())
    except Exception:
        pass
    return "version unknown"


def _ocio_normalize_config_path(config_path: str) -> str:
    """Resolve local OCIO configs relative to this project, never the launch CWD."""
    value = os.path.expandvars(os.path.expanduser(str(config_path or "").strip().strip('"')))
    if not value:
        value = OCIO_DEFAULT_CONFIG
    if value.casefold().startswith("ocio://"):
        return value
    candidate = Path(value)
    if not candidate.is_absolute():
        candidate = ROOT / candidate
    try:
        return str(candidate.resolve())
    except OSError:
        return str(candidate.absolute())


def _ocio_load_config(config_path: str):
    """Load/cache an OCIO config from a local .ocio file or OCIO built-in URI.

    Local config paths are anchored to the CorridorKey folder. This prevents a
    shortcut's Start-in directory or a different computer's current directory
    from silently changing which config is loaded.
    """
    path = _ocio_normalize_config_path(config_path)
    if not HAVE_OCIO or _OCIO is None:
        return None, (f"OpenColorIO Python binding not installed ({_OCIO_IMPORT_ERROR}). "
                      'Install with: python -m pip install "opencolorio>=2.5,<2.7".')
    if not path.casefold().startswith("ocio://") and not Path(path).is_file():
        return None, (f"OCIO config file not found: {path}. Move the config and its LUT/resource folders "
                      "inside the CorridorKey project, or select the built-in ACES CG config.")
    with _OCIO_CONFIG_CACHE_LOCK:
        cached = _OCIO_CONFIG_CACHE.get(path)
        if cached is not None:
            return cached[0], cached[1]
    try:
        config = _OCIO.Config.CreateFromFile(path)
        # Force a validation and populate the display/view data before exposing it to the UI.
        _ = list(config.getDisplays())
        result = (config, "")
    except Exception as exc:
        version = _ocio_version_text()
        result = (None, f"Could not load OCIO config '{path}' with OpenColorIO {version}: {type(exc).__name__}: {exc}")
    with _OCIO_CONFIG_CACHE_LOCK:
        _OCIO_CONFIG_CACHE[path] = result
    return result

def _ocio_config_metadata(config_path: str):
    """Return display/view choices, mapping, color-space names, default choice and status."""
    config, error = _ocio_load_config(config_path)
    if config is None:
        return [], {}, [], "", error
    choices, mapping = [], {}
    try:
        displays = list(config.getDisplays())
        default_display = str(config.getDefaultDisplay() or (displays[0] if displays else ""))
        default_view = str(config.getDefaultView(default_display) or "") if default_display else ""
        for display in displays:
            try:
                views = list(config.getViews(display))
            except Exception:
                views = []
            for view in views:
                label = f"{display}  /  {view}"
                if label in mapping:
                    label = f"{display}  /  {view} [{len(choices) + 1}]"
                choices.append(label)
                mapping[label] = {"display": str(display), "view": str(view)}
        try:
            colors = list(config.getColorSpaceNames())
        except Exception:
            colors = []
        default_label = next((label for label, pair in mapping.items()
                              if pair["display"] == default_display and pair["view"] == default_view),
                             choices[0] if choices else "")
        if not choices:
            return [], {}, colors, "", "The loaded OCIO config has no display/view pairs."
        return choices, mapping, colors, default_label, (f"Loaded OCIO { _ocio_version_text() } config: "
                                                            f"{config_path} · {len(choices)} display/view options")
    except Exception as exc:
        return [], {}, [], "", f"OCIO config inspection failed: {type(exc).__name__}: {exc}"

def _ocio_parse_selection(selection: str):
    try:
        value = json.loads(selection) if isinstance(selection, str) else selection
        return value if isinstance(value, dict) else {}
    except (ValueError, TypeError, json.JSONDecodeError):
        return {}

# Cache only EXR headers, not decoded pixels, so automatic input tagging stays cheap.
_EXR_HEADER_TAG_CACHE = OrderedDict()
_EXR_HEADER_TAG_CACHE_LOCK = threading.RLock()
_EXR_HEADER_TAG_CACHE_LIMIT = 2048


def _read_exr_header_tags(source_path: Path) -> dict:
    """Read the first EXR part's metadata without decompressing image pixels.

    OpenEXR headers are null-terminated name/type pairs followed by a little-endian
    size and payload. We read only the header so previewing a large EXR doesn't
    trigger a second full decode just to discover its color-space tag.
    """
    try:
        st = source_path.stat()
        key = (str(source_path.resolve()), int(st.st_size), int(st.st_mtime_ns))
    except OSError:
        return {}
    with _EXR_HEADER_TAG_CACHE_LOCK:
        cached = _EXR_HEADER_TAG_CACHE.get(key)
        if cached is not None:
            _EXR_HEADER_TAG_CACHE.move_to_end(key)
            return dict(cached)

    tags = {}
    try:
        with source_path.open("rb") as f:
            if f.read(4) != b"\x76\x2f\x31\x01":  # OpenEXR magic
                return {}
            if len(f.read(4)) != 4:  # version/flags
                return {}
            bytes_read = 8
            for _ in range(4096):
                # Attribute name (empty name ends the first part header).
                name_bytes = bytearray()
                while bytes_read < 8 * 1024 * 1024:
                    ch = f.read(1)
                    bytes_read += len(ch)
                    if not ch or ch == b"\0":
                        break
                    name_bytes.extend(ch)
                if not name_bytes:
                    break
                attr_type_bytes = bytearray()
                while bytes_read < 8 * 1024 * 1024:
                    ch = f.read(1)
                    bytes_read += len(ch)
                    if not ch or ch == b"\0":
                        break
                    attr_type_bytes.extend(ch)
                size_bytes = f.read(4)
                if len(size_bytes) != 4:
                    break
                bytes_read += 4
                size = struct.unpack("<I", size_bytes)[0]
                # Metadata of interest is tiny; guard against corrupt headers.
                if size > 4 * 1024 * 1024 or bytes_read + size > 8 * 1024 * 1024:
                    break
                payload = f.read(size)
                if len(payload) != size:
                    break
                bytes_read += size
                name = name_bytes.decode("utf-8", "replace")
                attr_type = attr_type_bytes.decode("ascii", "replace")
                value = payload
                try:
                    if attr_type == "string":
                        value = payload.decode("utf-8", "replace").rstrip("\0")
                    elif attr_type == "int" and size == 4:
                        value = struct.unpack("<i", payload)[0]
                    elif attr_type == "float" and size == 4:
                        value = struct.unpack("<f", payload)[0]
                    elif attr_type == "chromaticities" and size == 32:
                        value = struct.unpack("<8f", payload)
                except (ValueError, struct.error):
                    pass
                tags[name] = value
    except (OSError, ValueError, struct.error):
        return {}

    with _EXR_HEADER_TAG_CACHE_LOCK:
        _EXR_HEADER_TAG_CACHE[key] = dict(tags)
        _EXR_HEADER_TAG_CACHE.move_to_end(key)
        while len(_EXR_HEADER_TAG_CACHE) > _EXR_HEADER_TAG_CACHE_LIMIT:
            _EXR_HEADER_TAG_CACHE.popitem(last=False)
    return tags


def _ocio_resolve_colorspace_name(config, candidate: str) -> str:
    """Resolve a metadata name or alias against the active OCIO config."""
    candidate = str(candidate or "").strip().strip("\x00")
    if not candidate:
        return ""
    for method_name in ("getColorSpace", "findColorSpaceForID"):
        method = getattr(config, method_name, None)
        if not callable(method):
            continue
        try:
            color_space = method(candidate)
            if color_space:
                name_method = getattr(color_space, "getName", None)
                resolved = str(name_method() if callable(name_method) else color_space).strip()
                if resolved:
                    return resolved
        except Exception:
            pass
    try:
        canonical = str(config.getCanonicalName(candidate) or "").strip()
        if canonical and config.getColorSpace(canonical):
            return canonical
    except Exception:
        pass
    try:
        known = {str(n).casefold(): str(n) for n in config.getColorSpaceNames()}
        return known.get(candidate.casefold(), "")
    except Exception:
        return ""


def _ocio_detect_exr_input_space(config, source_path: Path) -> tuple[str, str]:
    """Detect an EXR input space from Color Interop ID, common tags or primaries.

    An EXR without identifying metadata cannot be known with certainty. In that
    case the OCIO file rule and then the app's ACEScg fallback are used.
    """
    tags = _read_exr_header_tags(source_path)
    if not tags:
        return "", "no readable EXR header metadata"

    # OpenEXR 3.4's standard portable color-space tag (e.g. lin_ap1_scene).
    interop_id = tags.get("colorInteropID")
    if isinstance(interop_id, str) and interop_id.strip():
        resolver = getattr(config, "findColorSpaceForID", None)
        if callable(resolver):
            try:
                cs = resolver(interop_id.strip())
                if cs:
                    name = str(cs.getName() if callable(getattr(cs, "getName", None)) else cs)
                    if name:
                        return name, f"colorInteropID={interop_id.strip()}"
            except Exception:
                pass
        resolved = _ocio_resolve_colorspace_name(config, interop_id)
        if resolved:
            return resolved, f"colorInteropID={interop_id.strip()}"

    # Explicit application metadata from common DCC/rendering tools.
    string_keys = (
        "ocio:colorspace", "ocio:ColorSpace", "oiio:ColorSpace", "ColorSpace",
        "colorspace", "colorSpace", "color_space", "inputColorSpace",
        "InputColorSpace", "aces:colorspace", "acesColorSpace", "sourceColorSpace",
    )
    tag_lookup = {str(k).casefold(): v for k, v in tags.items()}
    for key in string_keys:
        value = tag_lookup.get(key.casefold())
        if isinstance(value, str) and value.strip():
            resolved = _ocio_resolve_colorspace_name(config, value)
            if resolved:
                return resolved, f"{key}={value.strip()}"

    # The ACES Image Container flag formally implies ACES2065-1 / AP0.
    try:
        if int(tags.get("acesImageContainerFlag", 0)) == 1:
            for candidate in ("ACES2065-1", "ACES - ACES2065-1", "lin_ap0_scene"):
                resolved = _ocio_resolve_colorspace_name(config, candidate)
                if resolved:
                    return resolved, "acesImageContainerFlag=1 (ACES2065-1)"
    except (TypeError, ValueError):
        pass

    # If a writer supplied standard chromaticities, recognize common AP0, AP1,
    # and Rec.709 primaries. Chromaticities are identifying metadata, unlike EXR's
    # file extension alone.
    chroma = tags.get("chromaticities")
    if isinstance(chroma, tuple) and len(chroma) == 8:
        profiles = (
            ((0.7347, 0.2653, 0.0000, 1.0000, 0.0001, -0.0770, 0.32168, 0.33767),
             ("ACES2065-1", "ACES - ACES2065-1", "lin_ap0_scene"), "chromaticities=ACES AP0"),
            ((0.7130, 0.2930, 0.1650, 0.8300, 0.1280, 0.0440, 0.32168, 0.33767),
             ("ACEScg", "lin_ap1_scene"), "chromaticities=ACES AP1"),
            ((0.6400, 0.3300, 0.3000, 0.6000, 0.1500, 0.0600, 0.3127, 0.3290),
             ("Linear Rec.709", "Linear Rec709", "Rec.709", "Rec.709 / sRGB", "lin_rec709_scene"),
             "chromaticities=Rec.709"),
        )
        for expected, candidates, reason in profiles:
            if max(abs(float(a) - b) for a, b in zip(chroma, expected)) <= 0.004:
                for candidate in candidates:
                    resolved = _ocio_resolve_colorspace_name(config, candidate)
                    if resolved:
                        return resolved, reason

    return "", "EXR has no recognized color-space tag"


def _ocio_file_rule_input_space(config, source_path: Path) -> tuple[str, str]:
    """Return a color space only when an explicit OCIO file rule matched.

    PyOpenColorIO 2.5's Python binding returns (color-space, rule-index), not
    a bare string. Older bindings may return just the color-space name. The
    previous code stringified the tuple, so file-rule matches could never be
    resolved and the failure was silently ignored.
    """
    path_text = str(Path(source_path).resolve())
    only_default = None
    default_check = getattr(config, "filepathOnlyMatchesDefaultRule", None)
    if callable(default_check):
        try:
            only_default = bool(default_check(path_text))
        except Exception:
            only_default = None

    try:
        result = config.getColorSpaceFromFilepath(path_text)
    except Exception as exc:
        return "", f"OCIO file-rule lookup failed: {type(exc).__name__}: {exc}"

    rule_index = None
    raw_space = result
    if isinstance(result, (tuple, list)):
        raw_space = result[0] if result else ""
        if len(result) > 1:
            try:
                rule_index = int(result[1])
            except (TypeError, ValueError):
                rule_index = None

    # Compatibility fallback for bindings/configs which lack the convenience API.
    if only_default is None and rule_index is not None:
        try:
            rules = config.getFileRules()
            default_index = int(rules.getIndexForRule("Default"))
            only_default = (rule_index == default_index)
        except Exception:
            only_default = None

    if only_default is True:
        return "", "OCIO Default file rule only; using the configured EXR fallback"

    raw_space = str(raw_space or "").strip()
    resolved = _ocio_resolve_colorspace_name(config, raw_space)
    if resolved:
        return resolved, "matched an explicit OCIO file rule"
    return "", "no explicit OCIO file rule matched"


def _ocio_choose_input_space(config, source_path: Path, selection: dict, is_float_source: bool,
                             return_reason: bool = False):
    """Choose an OCIO input space for EXR files only.

    Video inputs (including MP4 and MOV) deliberately bypass OCIO so their
    existing decode/display appearance is preserved. When requested, return
    the reason for the chosen input space for clear diagnostics in the UI log.
    """
    def chosen(name: str, reason: str):
        return (name, reason) if return_reason else name

    if Path(source_path).suffix.lower() != ".exr":
        return chosen("", "OCIO input tagging is currently EXR-only")
    try:
        names = list(config.getColorSpaceNames())
    except Exception:
        names = []
    exact = {str(name).casefold(): str(name) for name in names}

    # EXR header metadata is authoritative when it identifies a known space.
    if bool(selection.get("input_tagging", True)):
        detected, reason = _ocio_detect_exr_input_space(config, source_path)
        if detected:
            return chosen(detected, f"EXR metadata: {reason}")

    # Use OCIO file rules, but do not mistake the catch-all Default rule for
    # a detected input tag. A default-only match must fall through to exr_input.
    file_rule_space, file_rule_reason = _ocio_file_rule_input_space(config, source_path)
    if file_rule_space:
        return chosen(file_rule_space, file_rule_reason)

    preferred = [selection.get("exr_input", "ACEScg"), "ACEScg", "ACES2065-1",
                 "Linear Rec.709", "Rec.709 / sRGB"]
    for name in preferred:
        candidate = str(name or "").strip()
        found = exact.get(candidate.casefold()) or _ocio_resolve_colorspace_name(config, candidate)
        if found:
            tag_mode = "automatic tagging disabled" if not bool(selection.get("input_tagging", True)) else "no usable metadata/file rule"
            return chosen(found, f"configured EXR fallback ({tag_mode}); {file_rule_reason}")

    if is_float_source:
        for name in names:
            if "acescg" in str(name).casefold():
                return chosen(str(name), "floating-point EXR fallback to ACEScg")
    for name in names:
        if "srgb" in str(name).casefold() and "texture" in str(name).casefold():
            return chosen(str(name), "config fallback to sRGB texture")
    if names:
        return chosen(str(names[0]), "first available OCIO color space fallback")
    return chosen("", "the active OCIO config has no color spaces")

def _ocio_processor(config_path: str, source_space: str, display: str, view: str):
    key = (str(config_path), str(source_space), str(display), str(view))
    with _OCIO_PROCESSOR_CACHE_LOCK:
        processor = _OCIO_PROCESSOR_CACHE.get(key)
    if processor is not None:
        return processor
    config, error = _ocio_load_config(config_path)
    if config is None:
        raise RuntimeError(error)
    if not source_space:
        raise RuntimeError("No suitable OCIO input color space was found in the selected config.")
    processor = config.getProcessor(source_space, display, view, _OCIO.TRANSFORM_DIR_FORWARD).getDefaultCPUProcessor()
    with _OCIO_PROCESSOR_CACHE_LOCK:
        _OCIO_PROCESSOR_CACHE[key] = processor
        while len(_OCIO_PROCESSOR_CACHE) > 48:
            _OCIO_PROCESSOR_CACHE.pop(next(iter(_OCIO_PROCESSOR_CACHE)))
    return processor

def _ocio_transform_rgb(rgb: np.ndarray, source_path: Path, selection: str, is_float_source: bool = False,
                        diagnostics: dict | None = None):
    """Apply OCIO to EXR pixels only; all non-EXR inputs are returned unchanged."""
    # Keep MP4/MOV and all other non-EXR media on the original preview path.
    # OCIO is intentionally restricted to EXR input so video appearance does not change.
    if Path(source_path).suffix.lower() != ".exr":
        return None
    if not HAVE_OCIO or _OCIO is None or not selection:
        if diagnostics is not None:
            diagnostics.update({"ocio_checked": True, "ocio_applied": False,
                                "ocio_error": "OpenColorIO is unavailable or no OCIO view is selected"})
        return None
    spec = _ocio_parse_selection(selection)
    config_path = str(spec.get("config") or OCIO_DEFAULT_CONFIG)
    display = str(spec.get("display") or "")
    view = str(spec.get("view") or "")
    if not display or not view:
        if diagnostics is not None:
            diagnostics.update({"ocio_checked": True, "ocio_applied": False,
                                "ocio_error": "No active OCIO display/view is selected"})
        return None
    config, error = _ocio_load_config(config_path)
    if config is None:
        if diagnostics is not None:
            diagnostics.update({"ocio_checked": True, "ocio_applied": False, "ocio_error": error})
        raise RuntimeError(error)
    source_space, tag_reason = _ocio_choose_input_space(
        config, source_path, spec, is_float_source, return_reason=True)
    if diagnostics is not None:
        diagnostics.update({"ocio_checked": True, "ocio_applied": False,
                            "ocio_source_space": source_space, "ocio_tag_reason": tag_reason,
                            "ocio_display": display, "ocio_view": view})
    processor = _ocio_processor(config_path, source_space, display, view)
    output = np.ascontiguousarray(rgb, dtype=np.float32).copy()
    processor.applyRGB(output)
    if diagnostics is not None:
        diagnostics["ocio_applied"] = True
    return np.clip(output, 0.0, 1.0)

def _ocio_transform_pil(image: Image.Image, source_path: Path, selection: str) -> Image.Image:
    """Keep decoded video frames unchanged; OCIO is reserved for EXR inputs."""
    # This helper is used by the video decoder. MP4/MOV and other video frames
    # must retain the app's existing decode/display color without an OCIO transform.
    if Path(source_path).suffix.lower() != ".exr":
        return image
    if not HAVE_OCIO or not selection:
        return image
    rgba = np.asarray(image.convert("RGBA"), dtype=np.uint8)
    rgb = rgba[:, :, :3].astype(np.float32) / 255.0
    try:
        transformed = _ocio_transform_rgb(rgb, source_path, selection, is_float_source=False)
    except Exception:
        transformed = None
    if transformed is None:
        return image
    out = np.empty_like(rgba)
    out[:, :, :3] = np.clip(transformed * 255.0 + 0.5, 0, 255).astype(np.uint8)
    out[:, :, 3] = rgba[:, :, 3]
    return Image.fromarray(out, "RGBA")

# OpenCV disables EXR codecs by default in some builds for security reasons.
# Force-enable before importing cv2, and also pass it to the render subprocess.
os.environ["OPENCV_IO_ENABLE_OPENEXR"] = "1"

from PIL import Image, ImageDraw, ImageFilter, ImageFont, ImageOps, ImageTk  # noqa: E402

