def _make_interface_palette(
    *, bg, card, field, sep, accent, accent_hover, accent_dim,
    subtle, gray_btn, gray_btn_hover, track, off_accent, preview_bg,
    light_accent=None, text_color="#F1F7F7",
):
    """Build a complete Light/Dark palette; keep the existing light neutrals."""
    light = _CLASSIC_INTERFACE_PALETTE
    light_accent = light_accent or accent
    return {
        "BG": (light["BG"][0], bg),
        "CARD": (light["CARD"][0], card),
        "FIELD": (light["FIELD"][0], field),
        "SEP": (light["SEP"][0], sep),
        "TEXT": (light["TEXT"][0], text_color),
        "SUBTLE": (light["SUBTLE"][0], subtle),
        "ACCENT": (light["ACCENT"][0] if light_accent == accent else light_accent, accent),
        "ACCENT_HOVER": (light["ACCENT_HOVER"][0], accent_hover),
        "ACCENT_DIM": (light["ACCENT_DIM"][0], accent_dim),
        "ON_ACCENT": (light["ON_ACCENT"][0], "#08110A"),
        "SUCCESS": (light["SUCCESS"][0], accent),
        "RED": (light["RED"][0], "#FF535D"),
        "ORANGE": (light["ORANGE"][0], "#FFB547"),
        "GRAY_BTN": (light["GRAY_BTN"][0], gray_btn),
        "GRAY_BTN_HOVER": (light["GRAY_BTN_HOVER"][0], gray_btn_hover),
        "DISABLED_TEXT": (light["DISABLED_TEXT"][0], "#718287"),
        "TRACK": (light["TRACK"][0], track),
        "OFF_ACCENT": (light["OFF_ACCENT"][0], off_accent),
        "PV_BG": (light["PV_BG"][0], preview_bg),
    }


