def _apply_interface_theme(theme_name: str) -> str:
    """Apply a complete interface palette before widgets are created."""
    global BG, CARD, FIELD, SEP, TEXT, SUBTLE
    global ACCENT, ACCENT_HOVER, ACCENT_DIM, ON_ACCENT
    global SUCCESS, RED, ORANGE, GRAY_BTN, GRAY_BTN_HOVER
    global DISABLED_TEXT, TRACK, OFF_ACCENT, PV_BG
    selected = theme_name if theme_name in _INTERFACE_PALETTES else DEFAULT_INTERFACE_THEME
    palette = _INTERFACE_PALETTES[selected]
    for key, value in palette.items():
        globals()[key] = value
    BADGE["READY"] = (ACCENT, ON_ACCENT)
    BADGE["DONE"] = (SUCCESS, ("#FFFFFF", "#08110A"))
    return selected
