_SONY_LUT_LOCK = threading.RLock()
_SONY_LUT_TABLE_CACHE = {}
_SONY_LUT_LOAD_ERROR = ""
_SONY_LUT_PROCESS_CACHE = {}
_SONY_LUT_PROCESSOR_ERROR = ""
_VIDEO_COLOR_META_CACHE = OrderedDict()
_VIDEO_COLOR_META_LOCK = threading.RLock()
_VIDEO_COLOR_META_LIMIT = 128
_SONY_LUT_LIBRARY_SIGNATURE_CACHE = None
_SONY_LUT_RESOLVE_CACHE = {}
_SONY_LUT_CUSTOM_ROOT: Path | None = None
_SONY_LUT_ENABLED = True
_SONY_LUT_AUTO_DETECT = True
_SONY_LUT_PREFERRED_LOOK = "Auto (recommended)"
_SONY_LUT_PROFILE_OVERRIDE = "Auto detect (metadata)"
SONY_LUT_PROFILE_CHOICES = [
    "Auto detect (metadata)",
    "Force S-Log2 / S-Gamut",
    "Force S-Log3 / S-Gamut3.Cine",
    "Force S-Log3 / S-Gamut3",
]
SONY_LUT_PROFILE_KEYS = {
    "Force S-Log2 / S-Gamut": "SLOG2_SGAMUT",
    "Force S-Log3 / S-Gamut3.Cine": "SLOG3_SGAMUT3CINE",
    "Force S-Log3 / S-Gamut3": "SLOG3_SGAMUT3",
}
SONY_LUT_LOOK_CHOICES = [
    "Auto (recommended)", "LC-709 Type A", "LC-709", "S-Log2-709", "Cine+709"
]


def _sony_lut_library_root() -> Path:
    custom = _SONY_LUT_CUSTOM_ROOT
    if custom is not None:
        try:
            custom = Path(custom).expanduser().resolve()
            if custom.is_dir():
                return custom
        except OSError:
            pass
    return ROOT / "resources" / "luts" / "sony"


def _sony_lut_library_files() -> list[Path]:
    root = _sony_lut_library_root()
    try:
        return sorted((p for p in root.rglob("*") if p.is_file() and p.suffix.casefold() == ".cube"),
                      key=lambda p: str(p).casefold()) if root.exists() else []
    except OSError:
        return []


def _sony_lut_library_signature() -> str:
    """Cache key component changes when official LUT files are installed/replaced.

    Computed once per app process; restart CorridorKey after installing/replacing the
    LUT library so cached preview frames and the LUT catalogue are rebuilt together.
    """
    global _SONY_LUT_LIBRARY_SIGNATURE_CACHE
    if _SONY_LUT_LIBRARY_SIGNATURE_CACHE is not None:
        return _SONY_LUT_LIBRARY_SIGNATURE_CACHE
    items = []
    for path in _sony_lut_library_files():
        try:
            st = path.stat()
            try:
                display_path = path.relative_to(ROOT).as_posix()
            except ValueError:
                display_path = str(path.resolve())
            items.append(f"{display_path}:{st.st_size}:{st.st_mtime_ns}")
        except OSError:
            continue
    items.append("embedded-user-lutcraft-slog3-v1")
    items.append(f"look={_SONY_LUT_PREFERRED_LOOK}")
    items.append(f"profile_override={_SONY_LUT_PROFILE_OVERRIDE}")
    items.append(f"enabled={int(bool(_SONY_LUT_ENABLED))};auto={int(bool(_SONY_LUT_AUTO_DETECT))}")
    _SONY_LUT_LIBRARY_SIGNATURE_CACHE = hashlib.sha256("\n".join(items).encode("utf-8", "replace")).hexdigest()[:20]
    return _SONY_LUT_LIBRARY_SIGNATURE_CACHE


def _normalise_lut_name(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", Path(str(value)).stem.casefold())


def _find_sony_lut(profile: str) -> tuple[Path | None, str]:
    """Select a Sony conversion LUT matching the detected S-Log/gamut and Preferences look."""
    cache_key = (str(profile), str(_SONY_LUT_PREFERRED_LOOK), _sony_lut_library_signature())
    with _SONY_LUT_LOCK:
        cached = _SONY_LUT_RESOLVE_CACHE.get(cache_key)
        if cached is not None:
            path_text, description = cached
            return (Path(path_text) if path_text else None), description

    files = _sony_lut_library_files()
    names = [(_normalise_lut_name(p.name), p) for p in files]
    def source_profile_token(name: str) -> str:
        # Sony filenames put the source profile before the `To` conversion token.
        # Looking at the entire filename would mistake an S-Log3-to-S-Log2-709 LUT
        # for an S-Log2 input LUT because `slog2` also appears in its output name.
        return name.split("to", 1)[0]

    if profile == "SLOG2_SGAMUT":
        family = lambda name: "slog2" in source_profile_token(name) and (
            "sgamut" in source_profile_token(name) or "sgumut" in source_profile_token(name))
        prefix = "Sony S-Log2 / S-Gamut"
    elif profile == "SLOG3_SGAMUT3CINE":
        family = lambda name: "slog3" in source_profile_token(name) and "sgamut3cine" in source_profile_token(name)
        prefix = "Sony S-Log3 / S-Gamut3.Cine"
    elif profile == "SLOG3_SGAMUT3":
        family = lambda name: (("sl3sg3" in source_profile_token(name) and "sg3c" not in source_profile_token(name))
                               or ("slog3" in source_profile_token(name)
                                   and "sgamut3" in source_profile_token(name)
                                   and "cine" not in source_profile_token(name)))
        prefix = "Sony S-Log3 / S-Gamut3"
    else:
        result = (None, f"Unsupported Sony Log profile: {profile}")
        return result

    look_tokens = {
        "LC-709 Type A": ("lc709typea",),
        "LC-709": ("lc709",),
        "S-Log2-709": ("slog2709",),
        "Cine+709": ("cine709", "cineplus709"),
    }
    preference = str(_SONY_LUT_PREFERRED_LOOK or "Auto (recommended)")
    if preference == "Auto (recommended)":
        order = ["LC-709 Type A", "LC-709", "S-Log2-709", "Cine+709"]
    else:
        order = [preference]

    match = None
    selected_look = ""
    for look in order:
        tokens = look_tokens.get(look, ())
        if not tokens:
            continue
        if look == "LC-709":
            match = next((p for n, p in names if family(n) and "lc709" in n and "lc709typea" not in n), None)
        else:
            match = next((p for token in tokens for n, p in names if family(n) and token in n), None)
        if match is not None:
            selected_look = look
            break

    if match is not None:
        description = f"{prefix} → {selected_look} ({match.name})"
        result = (str(match), description)
        with _SONY_LUT_LOCK:
            _SONY_LUT_RESOLVE_CACHE[cache_key] = result
        return Path(result[0]), result[1]

    # Compatibility with the previously supplied Lutcraft S-Log3 cube is limited to
    # automatic mode; an explicitly selected Sony look must not silently substitute another transform.
    if profile == "SLOG3_SGAMUT3CINE" and preference == "Auto (recommended)":
        legacy_candidates = [ROOT / "resources" / "luts" / "sony_slog3_to_rec709.cube",
                             ROOT / "LUTs" / "sony_slog3_to_rec709.cube",
                             ROOT / "sony_slog3_to_rec709.cube"]
        for candidate in legacy_candidates:
            if candidate.is_file():
                result = (str(candidate), "Fallback: previously supplied Lutcraft S-Log3→Rec.709 cube")
                with _SONY_LUT_LOCK:
                    _SONY_LUT_RESOLVE_CACHE[cache_key] = result
                return Path(result[0]), result[1]
        try:
            target = ROOT / "resources" / "luts" / "sony_slog3_to_rec709.cube"
            target.parent.mkdir(parents=True, exist_ok=True)
            payload = zlib.decompress(base64.b64decode(_SONY_SLOG3_LUT_ZLIB_B64))
            temp = target.with_suffix(f".tmp-{os.getpid()}.cube")
            temp.write_bytes(payload)
            os.replace(temp, target)
            result = (str(target), "Fallback: previously supplied Lutcraft S-Log3→Rec.709 cube")
            with _SONY_LUT_LOCK:
                _SONY_LUT_RESOLVE_CACHE[cache_key] = result
            return target, result[1]
        except Exception:
            pass

    installed = len(files)
    if preference == "Auto (recommended)":
        description = (f"No matching Sony LUT installed for {profile}. Found {installed} .cube file(s) in "
                       f"{_sony_lut_library_root()}. Install the matching Sony S-Log family or select an available look.")
    else:
        description = (f"Selected Sony look '{preference}' is not installed for {profile}. "
                       f"Found {installed} .cube file(s) in {_sony_lut_library_root()}.")
    result = ("", description)
    with _SONY_LUT_LOCK:
        _SONY_LUT_RESOLVE_CACHE[cache_key] = result
    return None, description


def _parse_cube_lut(path: Path):
    """Parse/cache an individual .cube LUT. Each Sony profile gets its own table."""
    global _SONY_LUT_LOAD_ERROR
    try:
        st = path.stat()
        key = (str(path.resolve()), int(st.st_size), int(st.st_mtime_ns))
    except OSError:
        key = (str(path),)
    with _SONY_LUT_LOCK:
        cached = _SONY_LUT_TABLE_CACHE.get(key)
        if cached is not None:
            return cached
    try:
        size = None
        domain_min = np.array([0.0, 0.0, 0.0], dtype=np.float32)
        domain_max = np.array([1.0, 1.0, 1.0], dtype=np.float32)
        values = []
        for raw in path.read_text(encoding="utf-8", errors="replace").splitlines():
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            key_name = parts[0].upper()
            if key_name in ("TITLE", "LUT_1D_SIZE"):
                continue
            if key_name == "LUT_3D_SIZE" and len(parts) >= 2:
                size = int(parts[1])
            elif key_name == "DOMAIN_MIN" and len(parts) >= 4:
                domain_min = np.asarray([float(v) for v in parts[1:4]], dtype=np.float32)
            elif key_name == "DOMAIN_MAX" and len(parts) >= 4:
                domain_max = np.asarray([float(v) for v in parts[1:4]], dtype=np.float32)
            elif len(parts) >= 3:
                try:
                    values.append((float(parts[0]), float(parts[1]), float(parts[2])))
                except ValueError:
                    continue
        if size is None or not (2 <= size <= 65) or len(values) != size ** 3:
            raise ValueError(f"Invalid 3D LUT '{path.name}': size={size}, rows={len(values)}")
        table = np.asarray(values, dtype=np.float32).reshape((size, size, size, 3))
        result = (table, domain_min, domain_max)
        with _SONY_LUT_LOCK:
            _SONY_LUT_TABLE_CACHE[key] = result
            while len(_SONY_LUT_TABLE_CACHE) > 24:
                _SONY_LUT_TABLE_CACHE.pop(next(iter(_SONY_LUT_TABLE_CACHE)))
        _SONY_LUT_LOAD_ERROR = ""
        return result
    except Exception as exc:
        _SONY_LUT_LOAD_ERROR = f"{type(exc).__name__}: {exc}"
        raise


def _ffprobe_executable() -> str:
    """Locate ffprobe, including next to a separately installed ffmpeg.exe."""
    found = shutil.which("ffprobe")
    if found:
        return found
    ffmpeg = shutil.which("ffmpeg")
    if ffmpeg:
        sibling = Path(ffmpeg).with_name("ffprobe.exe" if os.name == "nt" else "ffprobe")
        if sibling.is_file():
            return str(sibling)
    return "ffprobe"


def _metadata_strings(value, prefix="") -> list[tuple[str, str]]:
    result = []
    if isinstance(value, dict):
        for key, item in value.items():
            name = f"{prefix}.{key}" if prefix else str(key)
            result.extend(_metadata_strings(item, name))
    elif isinstance(value, (list, tuple)):
        for index, item in enumerate(value):
            result.extend(_metadata_strings(item, f"{prefix}[{index}]"))
    elif value is not None:
        result.append((str(prefix), str(value)))
    return result


def _sony_log_profile_from_text(text: str, sony_marker: bool = False) -> tuple[str | None, str]:
    """Identify Sony's supported Log/gamut combinations without guessing from camera brand alone."""
    value = str(text or "")
    slog2 = bool(re.search(r"s[\s_-]*log[\s_-]*2", value, re.IGNORECASE))
    slog3 = bool(re.search(r"s[\s_-]*log[\s_-]*3", value, re.IGNORECASE))
    gamut3_cine = bool(re.search(r"s[\s_-]*gamut[\s_-]*3\s*\.\s*cine|sgamut3\s*\.\s*cine", value, re.IGNORECASE))
    gamut3 = bool(re.search(r"s[\s_-]*gamut[\s_-]*3(?!\s*\.\s*cine)|sgamut3(?!\s*\.\s*cine)", value, re.IGNORECASE))
    gamut2 = bool(re.search(r"s[\s_-]*gamut(?![\s_-]*3)|sgamut(?!3)", value, re.IGNORECASE))
    pp = re.search(r"\bPP\s*[-_ ]?\s*([789])\b|picture[ _-]*profile\s*[:=]?\s*([789])\b", value, re.IGNORECASE)
    pp_num = next((g for g in pp.groups() if g), None) if pp else None

    if pp_num and sony_marker:
        if pp_num == "7":
            return "SLOG2_SGAMUT", "Sony Picture Profile PP7 (S-Log2 / S-Gamut)"
        if pp_num == "8":
            return "SLOG3_SGAMUT3CINE", "Sony Picture Profile PP8 (S-Log3 / S-Gamut3.Cine)"
        if pp_num == "9":
            return "SLOG3_SGAMUT3", "Sony Picture Profile PP9 (S-Log3 / S-Gamut3)"

    if slog2 and (sony_marker or gamut2 or gamut3 or gamut3_cine):
        gamut = "S-Gamut" if gamut2 else "S-Gamut (gamut not specified)"
        return "SLOG2_SGAMUT", f"Explicit Sony S-Log2 metadata; {gamut}"
    if slog3 and (sony_marker or gamut2 or gamut3 or gamut3_cine):
        if gamut3_cine:
            return "SLOG3_SGAMUT3CINE", "Explicit Sony S-Log3 / S-Gamut3.Cine metadata"
        if gamut3:
            return "SLOG3_SGAMUT3", "Explicit Sony S-Log3 / S-Gamut3 metadata"
        # An explicit Sony S-Log3 tag without gamut metadata is common in mirrorless files.
        return "SLOG3_SGAMUT3CINE", "Explicit Sony S-Log3 metadata (gamut unspecified; defaulting to S-Gamut3.Cine)"
    return None, "No definitive Sony S-Log2/S-Log3 profile metadata found"


def _sony_slog3_detection_from_metadata(metadata: dict, filename: str = "") -> tuple[str | None, str]:
    """Compatibility name retained; now returns a profile key for S-Log2 and S-Log3."""
    pairs = _metadata_strings(metadata)
    text_items = [f"{k}={v}" for k, v in pairs]
    combined = "\n".join(text_items)
    sony_marker = bool(re.search(r"\bsony\b|com\.sony|sony[-_ ]?(?:camera|corp|metadata)", combined, re.IGNORECASE))
    profile, reason = _sony_log_profile_from_text(combined, sony_marker=sony_marker)
    if profile:
        return profile, f"{reason}; metadata confirmed"

    filename_text = Path(filename).stem
    filename_profile, filename_reason = _sony_log_profile_from_text(filename_text, sony_marker=True)
    if filename_profile:
        return filename_profile, f"Explicit Sony Log filename hint: {filename_reason}"
    return None, reason


def _detect_sony_log_profile_from_exr(path: Path) -> tuple[str | None, str]:
    """Detect Sony Log tagging from an EXR header without guessing from .exr alone."""
    tags = _read_exr_header_tags(Path(path))
    if not tags:
        return None, "EXR header has no readable Sony Log metadata"
    pairs = _metadata_strings(tags)
    combined = "\n".join(f"{key}={value}" for key, value in pairs)
    sony_marker = bool(re.search(
        r"\bsony\b|com\.sony|sony[-_ ]?(?:camera|corp|metadata)",
        combined, re.IGNORECASE))
    profile, reason = _sony_log_profile_from_text(combined, sony_marker=sony_marker)
    if profile:
        return profile, f"{reason}; EXR metadata confirmed"
    # Filename detection is allowed only when it explicitly names a Sony Log profile.
    filename_profile, filename_reason = _sony_log_profile_from_text(Path(path).name, sony_marker=True)
    if filename_profile:
        return filename_profile, f"Explicit EXR filename hint: {filename_reason}"
    return None, "EXR metadata does not identify Sony S-Log2/S-Log3"


def _sony_profile_for_exr(path: Path, enabled_for_input: bool = True) -> tuple[str | None, str]:
    """Return a profile for an EXR only when enabled and confirmed/explicitly forced."""
    if not enabled_for_input:
        return None, "Sony LUT bypassed for generated output preview"
    if not _SONY_LUT_ENABLED:
        return None, "Sony LUT preview is disabled in Preferences"
    if _SONY_LUT_PROFILE_OVERRIDE in SONY_LUT_PROFILE_KEYS:
        profile = SONY_LUT_PROFILE_KEYS[_SONY_LUT_PROFILE_OVERRIDE]
        return profile, f"Manual Sony input profile override for EXR: {_SONY_LUT_PROFILE_OVERRIDE}"
    if _SONY_LUT_AUTO_DETECT:
        return _detect_sony_log_profile_from_exr(path)
    return None, "Auto detection is OFF; select a Force profile to apply a Sony LUT to this EXR"


def _detect_sony_log_profile(path: Path) -> tuple[str | None, str]:
    """Probe Sony camera metadata and sidecars once per file; never infer Log from Sony make alone."""
    if path.suffix.lower() not in VIDEO_EXTS:
        return None, "not a video input"
    try:
        stat = path.stat()
        sidecar_stats = []
        for sidecar in (path.with_suffix(".xml"), path.with_suffix(".XML")):
            try:
                st = sidecar.stat()
                sidecar_stats.append((str(sidecar), st.st_size, st.st_mtime_ns))
            except OSError:
                pass
        key = (str(path.resolve()), int(stat.st_size), int(stat.st_mtime_ns), tuple(sidecar_stats))
    except OSError:
        key = (str(path),)
    with _VIDEO_COLOR_META_LOCK:
        cached = _VIDEO_COLOR_META_CACHE.get(key)
        if cached is not None:
            _VIDEO_COLOR_META_CACHE.move_to_end(key)
            return cached

    metadata = {}
    probe_error = ""
    try:
        cmd = [_ffprobe_executable(), "-v", "error", "-show_streams", "-show_format", "-of", "json", str(path)]
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=12,
                              creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0)
        if proc.returncode == 0 and proc.stdout.strip():
            metadata = json.loads(proc.stdout)
        else:
            probe_error = (proc.stderr or f"ffprobe exit code {proc.returncode}").strip()[:500]
    except Exception as exc:
        probe_error = f"{type(exc).__name__}: {exc}"

    profile, reason = _sony_slog3_detection_from_metadata(metadata, path.name)
    # Sony XAVC/MXF camera workflows may store gamma, gamut and picture profile in XML sidecars.
    if profile is None:
        for sidecar in (path.with_suffix(".xml"), path.with_suffix(".XML")):
            try:
                if sidecar.is_file() and sidecar.stat().st_size <= 4 * 1024 * 1024:
                    side_text = sidecar.read_text(encoding="utf-8", errors="ignore")
                    sony_sidecar = bool(re.search(r"\bsony\b|com\.sony|SxS|XAVC", side_text, re.IGNORECASE))
                    side_profile, side_reason = _sony_log_profile_from_text(side_text, sony_marker=sony_sidecar)
                    if side_profile:
                        profile, reason = side_profile, f"{side_reason}; sidecar={sidecar.name}"
                        break
            except OSError:
                continue
    if profile is None and probe_error:
        reason = f"Sony Log not confirmed (ffprobe unavailable/failed: {probe_error}); source left unchanged"
    with _VIDEO_COLOR_META_LOCK:
        _VIDEO_COLOR_META_CACHE[key] = (profile, reason)
        _VIDEO_COLOR_META_CACHE.move_to_end(key)
        while len(_VIDEO_COLOR_META_CACHE) > _VIDEO_COLOR_META_LIMIT:
            _VIDEO_COLOR_META_CACHE.popitem(last=False)
    return profile, reason


def _sony_slog3_ocio_processor(lut_path: Path):
    """Build/cache a native OpenColorIO FileTransform processor for one cube LUT."""
    global _SONY_LUT_PROCESSOR_ERROR
    if not HAVE_OCIO or _OCIO is None:
        return None
    st = lut_path.stat()
    key = (str(lut_path.resolve()), int(st.st_mtime_ns), int(st.st_size))
    with _SONY_LUT_LOCK:
        cached = _SONY_LUT_PROCESS_CACHE.get(key)
        if cached is not None:
            return cached
    try:
        raw_config = _OCIO.Config.CreateRaw()
        file_transform = _OCIO.FileTransform()
        file_transform.setSrc(str(lut_path))
        interpolation = getattr(_OCIO, "INTERP_TETRAHEDRAL", None)
        if interpolation is not None:
            file_transform.setInterpolation(interpolation)
        processor = raw_config.getProcessor(file_transform).getDefaultCPUProcessor()
        with _SONY_LUT_LOCK:
            _SONY_LUT_PROCESS_CACHE[key] = processor
            while len(_SONY_LUT_PROCESS_CACHE) > 24:
                _SONY_LUT_PROCESS_CACHE.pop(next(iter(_SONY_LUT_PROCESS_CACHE)))
        _SONY_LUT_PROCESSOR_ERROR = ""
        return processor
    except Exception as exc:
        _SONY_LUT_PROCESSOR_ERROR = f"{type(exc).__name__}: {exc}"
        return None


def _apply_sony_log_lut_pil(image: Image.Image, profile: str) -> tuple[Image.Image, str, str]:
    """Apply the profile-matched Sony conversion LUT to preview Input only."""
    lut_path, lut_description = _find_sony_lut(profile)
    if lut_path is None:
        return image, "", lut_description
    if not HAVE_CV:
        return image, "", "NumPy/OpenCV unavailable; Sony LUT was not applied"
    try:
        rgba = np.asarray(image.convert("RGBA"), dtype=np.uint8)
        h, w = rgba.shape[:2]
        output = np.empty((h, w, 4), dtype=np.uint8)
        output[:, :, 3] = rgba[:, :, 3]
        processor = _sony_slog3_ocio_processor(lut_path)
        if processor is not None:
            for y0 in range(0, h, 256):
                y1 = min(y0 + 256, h)
                rgb = np.ascontiguousarray(rgba[y0:y1, :, :3].astype(np.float32) / 255.0)
                processor.applyRGB(rgb)
                output[y0:y1, :, :3] = np.clip(rgb * 255.0 + 0.5, 0, 255).astype(np.uint8)
            return Image.fromarray(output, "RGBA"), lut_path.name, f"Applied {lut_description}"

        # OpenCV fallback: cached per-file 3D LUT table and trilinear interpolation.
        table, domain_min, domain_max = _parse_cube_lut(lut_path)
        size = int(table.shape[0])
        domain_range = np.maximum(domain_max - domain_min, 1e-8)
        atlas = table.reshape((size * size, size, 3))
        for y0 in range(0, h, 256):
            y1 = min(y0 + 256, h)
            rgb = rgba[y0:y1, :, :3].astype(np.float32) / 255.0
            coord = np.clip((rgb - domain_min) / domain_range, 0.0, 1.0) * (size - 1)
            r, g, b = coord[:, :, 0], coord[:, :, 1], coord[:, :, 2]
            b0 = np.floor(b).astype(np.int32)
            b1 = np.minimum(b0 + 1, size - 1)
            bf = (b - b0)[..., None].astype(np.float32)
            map_x = np.ascontiguousarray(r, dtype=np.float32)
            map_y0 = np.ascontiguousarray(b0.astype(np.float32) * size + g, dtype=np.float32)
            map_y1 = np.ascontiguousarray(b1.astype(np.float32) * size + g, dtype=np.float32)
            slice0 = cv2.remap(atlas, map_x, map_y0, cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
            slice1 = cv2.remap(atlas, map_x, map_y1, cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
            result = slice0 * (1.0 - bf) + slice1 * bf
            output[y0:y1, :, :3] = np.clip(result * 255.0 + 0.5, 0, 255).astype(np.uint8)
        return Image.fromarray(output, "RGBA"), lut_path.name, f"Applied {lut_description}"
    except Exception as exc:
        return image, "", f"Sony LUT application failed for {lut_path.name}: {type(exc).__name__}: {exc}"


def _read_exr_with_openexr(path: Path):
    """Read EXR channels through the OpenEXR Python API, returning OpenCV-style pixels."""
    try:
        import OpenEXR
        with OpenEXR.File(str(path)) as exr:
            channels = exr.channels()
            pixels = {name: np.asarray(ch.pixels) for name, ch in channels.items()}
        # OpenEXR's high-level API groups RGB(A) planes by default unless
        # separate_channels=True is requested; handle both grouped and split forms.
        if "RGBA" in pixels:
            rgba = pixels["RGBA"]
            return np.ascontiguousarray(rgba[..., [2, 1, 0, 3]])  # RGBA -> BGRA
        if "RGB" in pixels:
            rgb = pixels["RGB"]
            return np.ascontiguousarray(rgb[..., ::-1])  # RGB -> BGR
        if "R" in pixels and "G" in pixels and "B" in pixels:
            bgr = np.stack((pixels["B"], pixels["G"], pixels["R"]), axis=-1)
            if "A" in pixels:
                return np.dstack((bgr, pixels["A"]))
            return bgr
        if "Y" in pixels:
            return pixels["Y"]
        if "A" in pixels:
            return pixels["A"]
        if pixels:
            return next(iter(pixels.values()))
    except Exception:
        return None
    return None


def _read_image(path: Path, ocio_selection: str = "", diagnostics: dict | None = None,
                preserve_encoded_values: bool = False) -> Image.Image:
    if not HAVE_CV:
        raise RuntimeError("Preview needs opencv-python and numpy")
    a = cv2.imread(str(path), cv2.IMREAD_UNCHANGED | cv2.IMREAD_ANYDEPTH | cv2.IMREAD_ANYCOLOR)
    if a is None and path.suffix.lower() == ".exr":
        a = _read_exr_with_openexr(path)
    if a is None:
        raise RuntimeError(f"Cannot read {path.name}; for DWAA/DWAB EXR preview, install OpenEXR>=3.3.")

    # OCIO operates on RGB float values; alpha is deliberately passed through untouched.
    is_float_source = np.issubdtype(a.dtype, np.floating)
    if np.issubdtype(a.dtype, np.integer):
        denom = float(np.iinfo(a.dtype).max)
        normalized = a.astype(np.float32) / max(denom, 1.0)
    else:
        normalized = a.astype(np.float32, copy=False)

    alpha = None
    if normalized.ndim == 2:
        rgb = np.repeat(normalized[:, :, None], 3, axis=2)
    elif normalized.ndim == 3 and normalized.shape[2] == 2:
        gray = normalized[:, :, 0]
        rgb = np.repeat(gray[:, :, None], 3, axis=2)
        alpha = normalized[:, :, 1]
    elif normalized.ndim == 3 and normalized.shape[2] == 3:
        rgb = normalized[:, :, :3][:, :, ::-1]  # OpenCV BGR -> RGB
    elif normalized.ndim == 3 and normalized.shape[2] >= 4:
        rgb = normalized[:, :, :3][:, :, ::-1]  # OpenCV BGRA -> RGB
        alpha = normalized[:, :, 3]
    else:
        raise RuntimeError(f"Unsupported channel layout in {path.name}: {normalized.shape}")

    transformed = None
    if not preserve_encoded_values:
        try:
            transformed = _ocio_transform_rgb(rgb, path, ocio_selection, is_float_source=is_float_source,
                                              diagnostics=diagnostics)
        except Exception as exc:
            # Color-management failure must not make the image viewer unusable.
            transformed = None
            global _LAST_OCIO_ERROR
            _LAST_OCIO_ERROR = f"{type(exc).__name__}: {exc}"
            if diagnostics is not None:
                diagnostics["ocio_checked"] = True
                diagnostics["ocio_applied"] = False
                diagnostics["ocio_error"] = _LAST_OCIO_ERROR
    if preserve_encoded_values:
        # Sony S-Log EXRs contain encoded camera values, not scene-linear pixels.
        # Preserve their normalized values for the Sony conversion LUT and do not
        # run an ACES input transform first (which would double-transform the data).
        rgb8 = np.clip(rgb * 255.0 + 0.5, 0, 255).astype(np.uint8)
    elif transformed is not None:
        rgb8 = np.clip(transformed * 255.0 + 0.5, 0, 255).astype(np.uint8)
    elif is_float_source:
        # Dependency-light fallback: map linear EXR values to a sensible Rec.709 preview.
        rgb8 = _linear_to_display(rgb, "Rec.709")
    else:
        rgb8 = np.clip(rgb * 255.0 + 0.5, 0, 255).astype(np.uint8)

    if alpha is None:
        alpha8 = np.full(rgb8.shape[:2], 255, dtype=np.uint8)
    else:
        alpha_scale = alpha.astype(np.float32, copy=False)
        if np.issubdtype(a.dtype, np.integer):
            alpha_scale = alpha_scale  # normalized above
        alpha8 = np.clip(alpha_scale * 255.0 + 0.5, 0, 255).astype(np.uint8)
    rgba = np.dstack((rgb8, alpha8))
    return Image.fromarray(rgba, "RGBA")

def _ffmpeg_frame(path: Path, t: float) -> Image.Image:
    cmd = ["ffmpeg", "-v", "error", "-ss", f"{t:.3f}", "-i", str(path), "-frames:v", "1",
           "-pix_fmt", "rgba", "-f", "image2pipe", "-vcodec", "png", "-"]
    flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    out = subprocess.run(cmd, capture_output=True, timeout=25, creationflags=flags).stdout
    if not out:
        raise RuntimeError("ffmpeg returned no frame")
    return Image.open(io.BytesIO(out)).convert("RGBA")


# Disk-backed preview frame cache. It lives beside this script so the cache is
# retained between launches. Entries are invalidated automatically when source
# size or modification time changes. PNG keeps alpha for EXR / cutout previews.
_PREVIEW_CACHE_DIR = ROOT / ".corridorkey_preview_cache"
_PREVIEW_CACHE_MAX_BYTES = 800 * 1024 * 1024
_PREVIEW_CACHE_TRIM_TO_BYTES = 650 * 1024 * 1024
_PREVIEW_CACHE_LOCK = threading.RLock()
_PREVIEW_CACHE_WRITES = 0
_PREVIEW_CACHE_VERSION = "v17-sony-log-exr-preview"


def _preview_cache_path(path: Path, frame_idx: int, ocio_selection: str, apply_sony_lut: bool = True, sony_profile: str = "") -> Path | None:
    try:
        resolved = path.resolve()
        stat = resolved.stat()
        signature = "\0".join((
            str(resolved), str(stat.st_size), str(stat.st_mtime_ns),
            str(frame_idx), ocio_selection, str(int(bool(apply_sony_lut))), str(sony_profile),
            _sony_lut_library_signature() if apply_sony_lut else "lut-bypassed", _PREVIEW_CACHE_VERSION,
        ))
        digest = hashlib.sha256(signature.encode("utf-8", "replace")).hexdigest()
        return _PREVIEW_CACHE_DIR / digest[:2] / f"{digest}.png"
    except (OSError, ValueError):
        return None


def _preview_cache_read(cache_path: Path | None):
    if cache_path is None or not cache_path.is_file():
        return None
    try:
        with Image.open(cache_path) as cached:
            image = cached.convert("RGBA").copy()
        source_size = image.size
        cache_metadata = {}
        metadata_path = cache_path.with_suffix(".json")
        if metadata_path.is_file():
            try:
                cache_metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
                size = cache_metadata.get("source_size")
                if isinstance(size, list) and len(size) == 2:
                    source_size = (int(size[0]), int(size[1]))
            except (OSError, ValueError, TypeError, json.JSONDecodeError):
                cache_metadata = {}
        return image, source_size, cache_metadata
    except Exception:  # Corrupt or incomplete cache: fall back to decoding source.
        return None


def _preview_cache_trim() -> None:
    """Trim least-recently-used disk cache entries when the configured limit is exceeded."""
    try:
        with _PREVIEW_CACHE_LOCK:
            entries = []
            total = 0
            for png in _PREVIEW_CACHE_DIR.glob("*/*.png"):
                try:
                    stat = png.stat()
                    total += stat.st_size
                    entries.append((stat.st_mtime, stat.st_size, png))
                except OSError:
                    continue
            if total <= _PREVIEW_CACHE_MAX_BYTES:
                return
            for _mtime, size, png in sorted(entries):
                try:
                    png.unlink(missing_ok=True)
                    png.with_suffix(".json").unlink(missing_ok=True)
                    total -= size
                except OSError:
                    pass
                if total <= _PREVIEW_CACHE_TRIM_TO_BYTES:
                    break
    except OSError:
        pass


def _preview_cache_write(cache_path: Path | None, image: Image.Image,
                         source_size: tuple[int, int], extra_metadata: dict | None = None) -> None:
    global _PREVIEW_CACHE_WRITES
    if cache_path is None:
        return
    try:
        with _PREVIEW_CACHE_LOCK:
            cache_path.parent.mkdir(parents=True, exist_ok=True)
            # Atomic replace prevents a second preview worker from reading a partial PNG.
            tag = f"{os.getpid()}-{threading.get_ident()}"
            temp_png = cache_path.with_name(f"{cache_path.stem}.{tag}.tmp.png")
            temp_json = cache_path.with_name(f"{cache_path.stem}.{tag}.tmp.json")
            image.save(temp_png, format="PNG", compress_level=1)
            metadata = {"source_size": list(source_size)}
            if isinstance(extra_metadata, dict):
                metadata.update(extra_metadata)
            temp_json.write_text(json.dumps(metadata), encoding="utf-8")
            os.replace(temp_png, cache_path)
            os.replace(temp_json, cache_path.with_suffix(".json"))
            _PREVIEW_CACHE_WRITES += 1
            do_trim = _PREVIEW_CACHE_WRITES % 96 == 0
        if do_trim:
            _preview_cache_trim()
    except OSError:
        # A read-only install folder should not prevent previews from working.
        try:
            temp_png.unlink(missing_ok=True)
            temp_json.unlink(missing_ok=True)
        except (OSError, UnboundLocalError):
            pass


def _load_frame_uncached(path: Path, frac: float, caps: dict | None = None, ocio_selection: str = "", apply_sony_lut: bool = True): 
    """Return a cached RGBA preview frame and metadata.

    A small PNG cache beside the script makes repeat playback and scrubbing much
    smoother. Video captures are kept thread-local by the caller; disk cache hits
    do not disturb their seek position, and the next uncached frame seeks safely.
    """
    info: dict = {"count": 1, "idx": 0, "fps": None}
    cache_path = None
    cache_hit = False
    source_size = None
    cache_metadata = {}

    if path.is_dir():
        files = sorted(p for p in path.iterdir() if p.suffix.lower() in IMAGE_EXTS)
        if not files:
            raise RuntimeError("No image frames in that folder")
        idx = round(frac * (len(files) - 1))
        source_path = files[idx]
        is_exr = source_path.suffix.lower() == ".exr"
        sony_log_profile, sony_log_reason = (
            _sony_profile_for_exr(source_path, enabled_for_input=apply_sony_lut)
            if is_exr else (None, "not an EXR input")
        )
        sony_lut_name = ""
        sony_lut_applied = False
        cache_path = _preview_cache_path(source_path, 0, ocio_selection, apply_sony_lut,
                                         sony_log_profile or "")
        cached = _preview_cache_read(cache_path)
        if cached is not None:
            img, source_size, cache_metadata = cached
            cache_hit = True
        else:
            # For a confirmed/forced Sony Log EXR, skip OCIO and preserve the
            # encoded Log values so the Sony conversion LUT receives the right data.
            img = _read_image(
                source_path,
                "" if sony_log_profile else ocio_selection,
                diagnostics=info,
                preserve_encoded_values=bool(sony_log_profile),
            )
            if sony_log_profile:
                img, sony_lut_name, apply_reason = _apply_sony_log_lut_pil(img, sony_log_profile)
                sony_lut_applied = bool(sony_lut_name)
                sony_log_reason = f"{sony_log_reason}; {apply_reason}"
            source_size = img.size
            cache_metadata = {k: info[k] for k in (
                "ocio_checked", "ocio_applied", "ocio_source_space", "ocio_tag_reason",
                "ocio_display", "ocio_view", "ocio_error") if k in info}
            cache_metadata.update({
                "sony_log_profile": sony_log_profile or "",
                "sony_lut_applied": bool(sony_lut_applied),
                "sony_lut_name": sony_lut_name,
                "sony_lut_reason": sony_log_reason,
            })
        if cache_hit:
            info.update({k: v for k, v in cache_metadata.items()
                         if k.startswith("ocio_") or k.startswith("sony_")})
            sony_log_profile = cache_metadata.get("sony_log_profile") or None
            sony_lut_applied = bool(cache_metadata.get("sony_lut_applied", False))
            sony_lut_name = str(cache_metadata.get("sony_lut_name", "") or "")
            sony_log_reason = str(cache_metadata.get("sony_lut_reason", sony_log_reason))
        if is_exr and apply_sony_lut:
            info.update(
                sony_lut_checked=True,
                sony_log_profile=sony_log_profile,
                sony_lut_applied=bool(sony_lut_applied),
                sony_lut_name=sony_lut_name,
                sony_lut_reason=sony_log_reason,
            )
        info.update(count=len(files), idx=idx, path=str(source_path))

    elif path.is_file() and path.suffix.lower() in IMAGE_EXTS:
        # A single still image is a valid one-frame source, not a video.
        # Read it directly instead of allowing it to reach VideoCapture.
        source_path = path
        is_exr = source_path.suffix.lower() == ".exr"
        sony_log_profile, sony_log_reason = (
            _sony_profile_for_exr(source_path, enabled_for_input=apply_sony_lut)
            if is_exr else (None, "not an EXR input")
        )
        img = _read_image(
            source_path,
            "" if sony_log_profile else ocio_selection,
            diagnostics=info,
            preserve_encoded_values=bool(sony_log_profile),
        )
        if sony_log_profile:
            img, sony_lut_name, apply_reason = _apply_sony_log_lut_pil(img, sony_log_profile)
            info.update(
                sony_lut_applied=bool(sony_lut_name),
                sony_lut_name=sony_lut_name,
                sony_log_profile=sony_log_profile,
                sony_lut_reason=f"{sony_log_reason}; {apply_reason}",
            )
        elif is_exr:
            info.update(
                sony_lut_applied=False,
                sony_log_profile="",
                sony_lut_name="",
                sony_lut_reason=sony_log_reason,
            )
        source_size = img.size
        info.update(count=1, idx=0, path=str(source_path))

    elif path.suffix.lower() in VIDEO_EXTS:
        if not HAVE_CV:
            raise RuntimeError("Preview needs opencv-python and numpy")
        if not apply_sony_lut:
            sony_log_profile, sony_log_reason = None, "Sony LUT bypassed for generated output preview"
        elif not _SONY_LUT_ENABLED:
            sony_log_profile, sony_log_reason = None, "Sony LUT preview is disabled in Preferences"
        elif _SONY_LUT_PROFILE_OVERRIDE in SONY_LUT_PROFILE_KEYS:
            sony_log_profile = SONY_LUT_PROFILE_KEYS[_SONY_LUT_PROFILE_OVERRIDE]
            sony_log_reason = f"Manual Sony input profile override: {_SONY_LUT_PROFILE_OVERRIDE}"
        elif _SONY_LUT_AUTO_DETECT:
            sony_log_profile, sony_log_reason = _detect_sony_log_profile(path)
        else:
            sony_log_profile, sony_log_reason = None, "Auto detection is OFF; choose a manual Sony input profile in Preferences"
        sony_lut_name = ""
        sony_lut_applied = False
        ent = None
        if caps is not None:
            ent = caps.get(str(path))
            if ent is None:
                if len(caps) >= 6:
                    old = caps.pop(next(iter(caps)))
                    try:
                        old[0].release()
                    except Exception:
                        pass
                ent = caps[str(path)] = [cv2.VideoCapture(str(path)), -1]
            cap = ent[0]
        else:
            cap = cv2.VideoCapture(str(path))
        count = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        fps = cap.get(cv2.CAP_PROP_FPS) or None
        idx = round(frac * (count - 1)) if count > 1 else 0
        cache_path = _preview_cache_path(path, idx, ocio_selection, apply_sony_lut, sony_log_profile or "")
        cached = _preview_cache_read(cache_path)
        if cached is not None:
            img, source_size, cache_metadata = cached
            cache_hit = True
            # The decoder may be positioned at a different frame. Force a seek on
            # the next cache miss rather than trusting its old sequential position.
            if ent is not None:
                ent[1] = -1
        else:
            img = None
            if path.name.lower().endswith("_cutout.mov"):
                try:
                    img = _ffmpeg_frame(path, (idx / fps) if fps else 0.0)
                except Exception:  # noqa: BLE001
                    img = None
            if img is None:
                if ent is None or ent[1] != idx - 1:
                    cap.set(cv2.CAP_PROP_POS_FRAMES, idx)
                ok, fr = cap.read()
                if ent is not None:
                    ent[1] = idx if ok else -1
                if not ok:
                    cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                    ok, fr = cap.read()
                    if ent is not None:
                        ent[1] = 0 if ok else -1
                if not ok:
                    if ent is not None:
                        caps.pop(str(path), None)
                    cap.release()
                    raise RuntimeError(f"Cannot decode {path.name}")
                img = Image.fromarray(cv2.cvtColor(fr, cv2.COLOR_BGR2RGBA), "RGBA")
            # MP4/MOV keeps its existing video color path; OCIO remains EXR-only.
            # The Sony LUT is applied only to confirmed Sony Log input, never generated outputs.
            img = _ocio_transform_pil(img, path, ocio_selection)
            if sony_log_profile:
                img, sony_lut_name, apply_reason = _apply_sony_log_lut_pil(img, sony_log_profile)
                sony_lut_applied = bool(sony_lut_name)
                sony_log_reason = f"{sony_log_reason}; {apply_reason}"
            source_size = img.size
            cache_metadata = {
                "sony_log_profile": sony_log_profile or "",
                "sony_lut_applied": bool(sony_lut_applied),
                "sony_lut_name": sony_lut_name,
                "sony_lut_reason": sony_log_reason,
            }
        if ent is None:
            cap.release()
        # Restore LUT status from the same disk-cache record as the pixels. Do not
        # claim a LUT was applied merely because a similarly named .cube exists.
        if cache_hit:
            sony_lut_name = str(cache_metadata.get("sony_lut_name", "") or "")
            sony_lut_applied = bool(cache_metadata.get("sony_lut_applied", False))
            if cache_metadata.get("sony_lut_reason"):
                sony_log_reason = str(cache_metadata["sony_lut_reason"])
        info.update(count=max(count, 1), idx=idx, fps=fps, path=str(path),
                    sony_lut_checked=bool(apply_sony_lut),
                    sony_log_profile=sony_log_profile,
                    sony_lut_applied=bool(sony_lut_applied),
                    sony_lut_name=sony_lut_name,
                    sony_lut_reason=sony_log_reason)

    else:
        is_exr = path.suffix.lower() == ".exr"
        sony_log_profile, sony_log_reason = (
            _sony_profile_for_exr(path, enabled_for_input=apply_sony_lut)
            if is_exr else (None, "not an EXR input")
        )
        sony_lut_name = ""
        sony_lut_applied = False
        cache_path = _preview_cache_path(path, 0, ocio_selection, apply_sony_lut,
                                         sony_log_profile or "")
        cached = _preview_cache_read(cache_path)
        if cached is not None:
            img, source_size, cache_metadata = cached
            cache_hit = True
        else:
            img = _read_image(
                path,
                "" if sony_log_profile else ocio_selection,
                diagnostics=info,
                preserve_encoded_values=bool(sony_log_profile),
            )
            if sony_log_profile:
                img, sony_lut_name, apply_reason = _apply_sony_log_lut_pil(img, sony_log_profile)
                sony_lut_applied = bool(sony_lut_name)
                sony_log_reason = f"{sony_log_reason}; {apply_reason}"
            source_size = img.size
            cache_metadata = {k: info[k] for k in (
                "ocio_checked", "ocio_applied", "ocio_source_space", "ocio_tag_reason",
                "ocio_display", "ocio_view", "ocio_error") if k in info}
            cache_metadata.update({
                "sony_log_profile": sony_log_profile or "",
                "sony_lut_applied": bool(sony_lut_applied),
                "sony_lut_name": sony_lut_name,
                "sony_lut_reason": sony_log_reason,
            })
        if cache_hit:
            info.update({k: v for k, v in cache_metadata.items()
                         if k.startswith("ocio_") or k.startswith("sony_")})
            sony_log_profile = cache_metadata.get("sony_log_profile") or None
            sony_lut_applied = bool(cache_metadata.get("sony_lut_applied", False))
            sony_lut_name = str(cache_metadata.get("sony_lut_name", "") or "")
            sony_log_reason = str(cache_metadata.get("sony_lut_reason", sony_log_reason))
        if is_exr and apply_sony_lut:
            info.update(
                sony_lut_checked=True,
                sony_log_profile=sony_log_profile,
                sony_lut_applied=bool(sony_lut_applied),
                sony_lut_name=sony_lut_name,
                sony_lut_reason=sony_log_reason,
            )
        info["path"] = str(path)

    if source_size is None:
        source_size = img.size
    info["size"] = source_size
    img.thumbnail((1280, 1280))
    if not cache_hit:
        _preview_cache_write(cache_path, img, source_size, cache_metadata)
    return img, info


# A bounded RAM cache makes frame stepping and repeated playback independent of
# disk PNG decode latency. The disk cache above still persists across launches.
_PREVIEW_MEMORY_CACHE: OrderedDict = OrderedDict()
_PREVIEW_MEMORY_LOCK = threading.RLock()
_PREVIEW_MEMORY_BYTES = 0
_PREVIEW_MEMORY_MAX_BYTES = 256 * 1024 * 1024
_PREVIEW_MEMORY_MAX_ITEMS = 72


def _preview_memory_key(path: Path, frac: float, ocio_selection: str, apply_sony_lut: bool = True):
    try:
        p = Path(path).resolve()
        st = p.stat()
        # The directory mtime/size changes when an image sequence is extended or
        # files are added. Individual file inputs include their full signature.
        signature = (st.st_size, st.st_mtime_ns, getattr(st, "st_ctime_ns", 0))
        lut_signature = _sony_lut_library_signature() if apply_sony_lut else "lut-bypassed"
        sony_settings = (
            bool(_SONY_LUT_ENABLED) if apply_sony_lut else False,
            bool(_SONY_LUT_AUTO_DETECT) if apply_sony_lut else False,
            str(_SONY_LUT_PROFILE_OVERRIDE) if apply_sony_lut else "",
            str(_SONY_LUT_PREFERRED_LOOK) if apply_sony_lut else "",
        )
        return (str(p), signature, round(float(frac), 7), str(ocio_selection),
                bool(apply_sony_lut), sony_settings, lut_signature, _PREVIEW_CACHE_VERSION)
    except (OSError, ValueError, TypeError):
        lut_signature = _sony_lut_library_signature() if apply_sony_lut else "lut-bypassed"
        sony_settings = (
            bool(_SONY_LUT_ENABLED) if apply_sony_lut else False,
            bool(_SONY_LUT_AUTO_DETECT) if apply_sony_lut else False,
            str(_SONY_LUT_PROFILE_OVERRIDE) if apply_sony_lut else "",
            str(_SONY_LUT_PREFERRED_LOOK) if apply_sony_lut else "",
        )
        return (str(path), round(float(frac), 7), str(ocio_selection),
                bool(apply_sony_lut), sony_settings, lut_signature, _PREVIEW_CACHE_VERSION)


def _preview_memory_get(key):
    with _PREVIEW_MEMORY_LOCK:
        item = _PREVIEW_MEMORY_CACHE.get(key)
        if item is None:
            return None
        _PREVIEW_MEMORY_CACHE.move_to_end(key)
        image, info, _cost = item
        return image.copy(), dict(info)


def _preview_memory_put(key, image: Image.Image, info: dict) -> None:
    global _PREVIEW_MEMORY_BYTES
    try:
        copy = image.copy()
        cost = max(copy.width * copy.height * 4, 1)
        if cost > _PREVIEW_MEMORY_MAX_BYTES:
            return
        with _PREVIEW_MEMORY_LOCK:
            previous = _PREVIEW_MEMORY_CACHE.pop(key, None)
            if previous is not None:
                _PREVIEW_MEMORY_BYTES -= previous[2]
            _PREVIEW_MEMORY_CACHE[key] = (copy, dict(info), cost)
            _PREVIEW_MEMORY_BYTES += cost
            while (_PREVIEW_MEMORY_BYTES > _PREVIEW_MEMORY_MAX_BYTES or
                   len(_PREVIEW_MEMORY_CACHE) > _PREVIEW_MEMORY_MAX_ITEMS):
                _old_key, old_item = _PREVIEW_MEMORY_CACHE.popitem(last=False)
                _PREVIEW_MEMORY_BYTES -= old_item[2]
    except Exception:
        pass


def load_frame(path: Path, frac: float, caps: dict | None = None, ocio_selection: str = "", apply_sony_lut: bool = True):
    """Return cached RGBA frame data; keep capture objects confined to the decoder thread."""
    key = _preview_memory_key(path, frac, ocio_selection, apply_sony_lut)
    cached = _preview_memory_get(key)
    if cached is not None:
        return cached
    image, info = _load_frame_uncached(path, frac, caps, ocio_selection, apply_sony_lut)
    _preview_memory_put(key, image, info)
    return image, info


def find_output(outdir: Path | None, tab: str) -> Path | None:
    if not outdir or not outdir.exists() or tab not in PV_PATTERNS:
        return None
    for pat in PV_PATTERNS[tab]:
        hits = sorted(outdir.glob(pat))
        if hits:
            return hits[0]
    return None


def checker_bg(size, tile: int = 14) -> Image.Image:
    w, h = size
    row = Image.new("RGB", (tile * 2, tile * 2), "#B9B9BD")
    d = ImageDraw.Draw(row)
    d.rectangle((0, 0, tile - 1, tile - 1), fill="#E6E6EA")
    d.rectangle((tile, tile, tile * 2 - 1, tile * 2 - 1), fill="#E6E6EA")
    bg = Image.new("RGB", (w, h))
    for y in range(0, h, tile * 2):
        for x in range(0, w, tile * 2):
            bg.paste(row, (x, y))
    return bg.convert("RGBA")


# ----------------------------------------------------------------------- app
class App(ctk.CTk):
    def __init__(self) -> None:
        super().__init__()
        self._preferences_path = ROOT / "corridorkey_preferences.json"
        self._preferences = self._load_preferences_file()
        self._previous_project_root = str(self._preferences.pop("_previous_project_root", "") or "")
        self._preferences["interface_theme"] = _apply_interface_theme(
            str(self._preferences.get("interface_theme", DEFAULT_INTERFACE_THEME)))
        # Theme controls colors; the active workspace controls the main arrangement.
        self._active_interface_theme = self._preferences["interface_theme"]
        saved_workspace_layout = str(
            self._preferences.get("workspace_layout", DEFAULT_WORKSPACE_LAYOUT))
        # Older preferences may still contain the retired PhotoCraft workspace.
        # Keep the PhotoCraft editor integration, but migrate the workspace choice.
        if saved_workspace_layout not in WORKSPACE_LAYOUT_CHOICES:
            saved_workspace_layout = DEFAULT_WORKSPACE_LAYOUT
        self._photocraft_workspace_enabled = False
        self._active_workspace_layout = saved_workspace_layout
        self._photocraft_process = None
        self._photocraft_hwnd = None
        self._photocraft_original_style = None
        self._photocraft_embedded = False
        self._photocraft_building = False
        self._photocraft_downloading = False
        self._photocraft_build_process = None
        self._photocraft_resize_job = None
        self._photocraft_open_dialog_after_start = False
        self._photocraft_pending_open_path = None
        self._photocraft_pending_hint_request = None
        self._workspace_switching = False
        self._workspace_page_by_layout = {
            "Classic": "Setup",
            "CorridorKey Studio": "Setup",
            "Queue Studio": "Setup",
            "PhotoCraft": "PhotoCraft",
        }
        # Remember per-workspace navigation/view state across in-process switches
        # and application launches. Only lightweight values are persisted here.
        _saved_workspace_pages = self._preferences.get("workspace_page_by_layout", {})
        if isinstance(_saved_workspace_pages, dict):
            for _workspace, _page in _saved_workspace_pages.items():
                if _workspace in self._workspace_page_by_layout and isinstance(_page, str):
                    _allowed = {
                        "Classic": {"Setup", "Media", "Queue", "CPU/GPU"},
                        "CorridorKey Studio": {"Setup", "CPU/GPU"},
                        "Queue Studio": {"Setup", "Media", "Model Brain", "CPU/GPU"},
                        "PhotoCraft": {"PhotoCraft"},
                    }.get(_workspace, set())
                    if _page in _allowed:
                        self._workspace_page_by_layout[_workspace] = _page
        _saved_workspace_views = self._preferences.get("workspace_view_state_by_layout", {})
        self._workspace_view_state_by_layout = (
            dict(_saved_workspace_views) if isinstance(_saved_workspace_views, dict) else {})
        # Short cross-fade uses a cached screen image, not animated widget geometry.
        # This hides the synchronous widget rebuild and avoids moving the dock itself.
        self._workspace_snapshot_cache = {}
        self._workspace_transition_overlay = None
        self._workspace_transition_photo = None
        self._workspace_transition_job = None
        self._workspace_transition_started = 0.0
        # Fast, subtle workspace reveal: 120 ms total at a 20 ms tick (~50 FPS).
        self._workspace_transition_duration = 0.12
        self._workspace_transition_interval_ms = 20
        self._workspace_transition_base_alpha = 0.96
        self._photocraft_hint_watch_state = None  # retained for older preferences/scripts
        self._photocraft_hint_watchers = {}
        self._photocraft_hint_export_targets = {}
        # PSD -> temporary first-frame seed. Removed only after that PSD exports
        # a valid replacement PNG hint successfully.
        self._photocraft_first_frame_sources = {}
        self._photocraft_hint_watch_job = None
        global _SONY_LUT_CUSTOM_ROOT, _SONY_LUT_ENABLED, _SONY_LUT_AUTO_DETECT
        global _SONY_LUT_PREFERRED_LOOK, _SONY_LUT_PROFILE_OVERRIDE
        _SONY_LUT_ENABLED = bool(self._preferences.get("sony_lut_enabled", True))
        _SONY_LUT_AUTO_DETECT = bool(self._preferences.get("sony_lut_auto_detect", True))
        _SONY_LUT_PREFERRED_LOOK = str(self._preferences.get("sony_lut_look", "Auto (recommended)"))
        _SONY_LUT_PROFILE_OVERRIDE = str(self._preferences.get("sony_lut_profile", "Auto detect (metadata)"))
        sony_dir = Path(self._preferences.get("sony_lut_dir", str(ROOT / "resources" / "luts" / "sony"))).expanduser()
        if not sony_dir.is_absolute():
            sony_dir = ROOT / sony_dir
        _SONY_LUT_CUSTOM_ROOT = sony_dir.resolve() if sony_dir.is_dir() else None
        self._preferences["project_root"] = str(ROOT)
        self._ocio_recovery_notice = str(self._preferences.pop("_ocio_recovery_notice", "") or "")
        self._ocio_config_path = _ocio_normalize_config_path(
            str(self._preferences.get("ocio_config_path", OCIO_DEFAULT_CONFIG)))
        (self._ocio_view_choices, self._ocio_view_map, self._ocio_color_spaces,
         self._ocio_default_view, self._ocio_status) = _ocio_config_metadata(self._ocio_config_path)
        if not self._ocio_view_choices:
            self._ocio_view_choices = [OCIO_UNAVAILABLE_LABEL if not HAVE_OCIO else "OCIO config unavailable"]
            self._ocio_view_map = {}
            self._ocio_default_view = self._ocio_view_choices[0]
        if not HAVE_OCIO:
            self._ocio_status = ("OpenColorIO Python binding is not installed. Install it in this app's environment with: "
                                 'python -m pip install "opencolorio>=2.5,<2.7". The selected ACES CG config is built into OCIO 2.5+.' )
        if self._ocio_recovery_notice:
            self._ocio_status = self._ocio_recovery_notice + "\n" + self._ocio_status
        self._preferences["ocio_config_path"] = self._ocio_config_path
        # Apply saved preview-cache location/limit before any preview worker starts.
        global _PREVIEW_CACHE_DIR, _PREVIEW_CACHE_MAX_BYTES, _PREVIEW_CACHE_TRIM_TO_BYTES
        try:
            cache_dir = Path(self._preferences.get("preview_cache_dir", str(ROOT / ".corridorkey_preview_cache"))).expanduser()
            if not cache_dir.is_absolute():
                cache_dir = ROOT / cache_dir
            limit_mb = int(self._preferences.get("preview_cache_limit_mb", 800))
            limit_mb = max(16, min(32768, limit_mb))
            _PREVIEW_CACHE_DIR = cache_dir.resolve()
            _PREVIEW_CACHE_MAX_BYTES = limit_mb * 1024 * 1024
            _PREVIEW_CACHE_TRIM_TO_BYTES = int(_PREVIEW_CACHE_MAX_BYTES * 0.85)
            self._preferences["preview_cache_dir"] = str(_PREVIEW_CACHE_DIR)
            self._preferences["preview_cache_limit_mb"] = limit_mb
        except (OSError, ValueError, TypeError):
            _PREVIEW_CACHE_DIR = ROOT / ".corridorkey_preview_cache"
            _PREVIEW_CACHE_MAX_BYTES = 800 * 1024 * 1024
            _PREVIEW_CACHE_TRIM_TO_BYTES = 650 * 1024 * 1024
            self._preferences["preview_cache_dir"] = str(_PREVIEW_CACHE_DIR)
            self._preferences["preview_cache_limit_mb"] = 800
        self._preferences_window = None
        # Render CUDA is checked in a subprocess so importing/initializing Torch never blocks Tk.
        self._render_gpu_probe_cache: dict | None = None
        self._render_gpu_probe_busy = False
        self._render_gpu_installing = False
        self._render_gpu_install_attempted = False
        self._render_gpu_probe_origin = "startup"
        self._pending_render_jobs = None
        self._preview_cuda_available = None
        self._preview_gpu_backend_cache = None
        self._preview_gpu_runtime_failed = False
        self._preview_torch_module = None
        self._preview_gpu_detection_done = False
        # Preview GPU work is deliberately restricted to active Wipe-divider drags.
        # It never changes render/task GPU behavior or accelerates other preview modes.
        self._wipe_gpu_dragging = False
        self._wipe_drag_active = False
        self._wipe_drag_target = "main"
        self._wipe_refresh_job = None
        self._wipe_drag_base_a: Image.Image | None = None
        self._wipe_drag_base_b: Image.Image | None = None
        # The same preview GPU setting also covers short, interactive pan/zoom
        # gestures in the detached preview window. It never affects render jobs.
        self._detached_gpu_interaction = False
        self._detached_gpu_release_job = None
        self._detached_fit_cache: OrderedDict = OrderedDict()
        self._detached_composite_cache_key = None
        self._detached_composite_cache_image = None
        self._last_logged_error_signature = None
        self._last_logged_error_at = 0.0
        ctk.set_appearance_mode(self._preferences.get("appearance", "Dark"))
        self.title("CorridorKey 2.0")
        self.configure(fg_color=BG)
        # Open at full opacity. Do not depend on delayed Tk callbacks to reveal the UI.
        try:
            self.attributes("-alpha", 1.0)
        except Exception:  # noqa: BLE001
            pass
        self._fit_to_screen()

        self.f_body = ctk.CTkFont(family=FONT, size=13)
        self.f_small = ctk.CTkFont(family=FONT, size=12)
        self.f_head = ctk.CTkFont(family=FONT, size=11, weight="bold")
        self.f_title = ctk.CTkFont(family=FONT, size=22, weight="bold")
        self.f_btn = ctk.CTkFont(family=FONT, size=15, weight="bold")
        self.f_timer = ctk.CTkFont(family=MONO, size=34, weight="bold")
        self.f_mono = ctk.CTkFont(family=MONO, size=11)

        self.proc: subprocess.Popen | None = None
        self.msgs: queue.Queue = queue.Queue()
        self._preview_gpu_resize_pending = set()
        self._preview_gpu_resize_results: OrderedDict = OrderedDict()
        self._preview_gpu_resize_cache_limit = 40
        self._preview_gpu_active_gen = 0
        self._preview_gpu_resize_executor = ThreadPoolExecutor(
            max_workers=1, thread_name_prefix="CorridorKeyPreviewGPU")
        self._flat_image_cache: OrderedDict = OrderedDict()
        self.stop_requested = False
        self.last_outdir: Path | None = None
        self._last_cr = False

        # stopwatch / progress state
        self.running = False
        self.t_start = self.clip_t0 = 0.0
        self.clip_info = ""
        self.frac: float | None = None
        # Queue Studio Model Brain telemetry. The installed infer.py currently
        # exposes process logs and overall progress, not per-layer activations;
        # the graph therefore reports observable/estimated pipeline activity.
        self.model_brain_stage = "idle"
        self.model_brain_active_clip = ""
        self.model_brain_active_qid = None
        self.model_brain_progress = None
        self.model_brain_last_event = "Awaiting render activity"
        self.model_brain_events = deque(maxlen=7)
        self.model_brain_stage_source = "No active render"
        # Model Brain's network visualization is a lightweight UI animation.
        # It is explicitly schematic because infer.py does not expose neuron activations.
        self.model_brain_anim_phase = 0.0
        self.model_brain_anim_job = None
        self.pb_det = True
