    def _log_tags(self) -> None:
        tb = self.log
        tb.tag_config("ok", foreground=resolve(SUCCESS))
        tb.tag_config("err", foreground=resolve(RED))
        tb.tag_config("head", foreground=resolve(TEXT))
        tb.tag_config("dim", foreground=resolve(SUBTLE))

    # ---------------------------------------------------------- history / preview
    def _history_state(self):
        vals = {}
        for name in ("v_input", "v_batch", "v_outdir", "v_mode", "v_hint", "v_hint_q", "v_carry_q", "v_no_carry",
                     "v_format", "v_despill", "v_cutout_linear", "v_frames_linear", "v_vram", "v_chunk", "v_stride",
                     "v_temp", "v_limit", "v_exr_compression", "v_preview_on", "v_ocio_exr_input",
                     "v_preview_bg_image", "v_preview_background"):
            var = getattr(self, name, None)
            if var is not None:
                vals[name] = var.get()
        vals["v_out"] = {k: v.get() for k, v in self.v_out.items()}
        vals["v_adv"] = {k: v.get() for k, v in self.v_adv.items()}
        return vals

    def _init_history(self):
        self._history = [self._history_state()]
        self._history_index = 0
        for name in ("v_input", "v_batch", "v_outdir", "v_mode", "v_hint", "v_hint_q", "v_carry_q", "v_no_carry",
                     "v_format", "v_despill", "v_cutout_linear", "v_frames_linear", "v_vram", "v_chunk", "v_stride",
                     "v_temp", "v_limit", "v_exr_compression", "v_preview_on", "v_ocio_exr_input",
                     "v_preview_background"):
            var = getattr(self, name)
            var.trace_add("write", lambda *_: self._history_changed())
        for var in self.v_out.values():
            var.trace_add("write", lambda *_: self._history_changed())
        for var in self.v_adv.values():
            var.trace_add("write", lambda *_: self._history_changed())
        self._update_history_buttons()

    def _history_changed(self):
        if self._history_busy:
            return
        state = self._history_state()
        if self._history and state == self._history[self._history_index]:
            return
        self._history = self._history[:self._history_index + 1]
        self._history.append(state)
        self._history = self._history[-50:]
        self._history_index = len(self._history) - 1
        self._update_history_buttons()

    def _apply_history(self, state):
        self._history_busy = True
        try:
            for name, value in state.items():
                if name in ("v_out", "v_adv"):
                    continue
                getattr(self, name).set(value)
            for k, v in state["v_out"].items():
                self.v_out[k].set(v)
            for k, v in state["v_adv"].items():
                self.v_adv[k].set(v)

            # Keep custom segmented controls visually aligned with restored settings.
            self.seg_mode.set(next(k for k, v in MODE_LABELS.items() if v == self.v_mode.get()))
            current_format = self.v_format.get()
            fmt_label = {"exr": "EXR (HDR)", "png": "PNG"}.get(current_format, "Video")
            if fmt_label == "PNG" and getattr(self, "_active_workspace_layout", "") != "Queue Studio":
                fmt_label = "Video"
            self.seg_fmt.set(fmt_label)
            self.seg_vram.set(next(k for k, v in VRAM_LABELS.items() if v == self.v_vram.get()))
            self._toggle_state()
            self._sync_preview_controls(request=False)
        finally:
            self._history_busy = False
        self._preview_bg_cache_key = None
        self._preview_background_changed()
        if self.v_preview_on.get():
            self._pv_request()
        self._update_history_buttons()

    def _undo(self):
        if self._history_index <= 0:
            return
        self._history_index -= 1
        self._apply_history(self._history[self._history_index])

    def _redo(self):
        if self._history_index >= len(self._history) - 1:
            return
        self._history_index += 1
        self._apply_history(self._history[self._history_index])

    def _update_history_buttons(self):
        if hasattr(self, "b_undo"):
            self.b_undo.configure(state="normal" if self._history_index > 0 else "disabled")
            self.b_redo.configure(state="normal" if self._history_index < len(self._history) - 1 else "disabled")

    def _sync_preview_controls(self, request: bool = True):
        on = bool(self.v_preview_on.get())
        self.b_pv_toggle.configure(text="Preview ON" if on else "Preview OFF")
        for widget in (self.seg_pv, self.seg_view, self.opt_cmp):
            widget.configure(state="normal" if on else "disabled")
        if not on:
            self._pv_stop_play()
            self._pv_message("Preview disabled")
        elif request:
            self._pv_request()

    def _toggle_preview(self):
        self.v_preview_on.set(not self.v_preview_on.get())
        self._sync_preview_controls(request=True)

    def _ocio_preview_spec(self) -> str:
        """Snapshot OCIO's automatic default display/view for all preview windows."""
        label = self._ocio_default_view or (self._ocio_view_choices[0] if self._ocio_view_choices else "")
        # Keep the internal legacy variable synchronized; there is no manual display-color control.
        try:
            if self.v_ocio_view.get() != label:
                self.v_ocio_view.set(label)
        except Exception:
            pass
        pair = self._ocio_view_map.get(label, {})
        revision = ""
        try:
            config_path = Path(self._ocio_config_path).expanduser()
            if not self._ocio_config_path.startswith("ocio://") and config_path.is_file():
                stat = config_path.stat()
                revision = f"{stat.st_size}:{stat.st_mtime_ns}"
        except OSError:
            pass
        names_cf = {str(name).casefold(): str(name) for name in self._ocio_color_spaces}
        exr_fallback = (names_cf.get("acescg") or names_cf.get("aces2065-1")
                        or names_cf.get("linear rec.709") or (self._ocio_color_spaces[0] if self._ocio_color_spaces else "ACEScg"))
        return json.dumps({
            "config": self._ocio_config_path, "display": pair.get("display", ""),
            "view": pair.get("view", ""), "exr_input": exr_fallback,
            "input_tagging": bool(getattr(self, "v_input_tagging", None).get()) if getattr(self, "v_input_tagging", None) is not None else True,
            "revision": revision,
        }, sort_keys=True)

    def _resize_preview_tab_control(self, event=None) -> None:
        """Let source tabs use the full top row; input format now sits beside frame metadata."""
        try:
            row = self.seg_pv.master
            width = int(getattr(event, "width", row.winfo_width())) - 2
            self.seg_pv.set_width(max(240, width))
        except Exception:
            pass

    def _input_format_label(self) -> str:
        """Return the selected input's short media type (EXR, MP4, MOV, etc.)."""
        raw = self.v_input.get().strip().strip('"') if hasattr(self, "v_input") else ""
        if not raw:
            return "—"
        path = Path(raw).expanduser()
        candidate = None
        try:
            if path.is_file():
                candidate = path
            elif path.is_dir():
                if bool(self.v_batch.get()):
                    candidates = sorted(p for p in path.iterdir()
                                        if p.is_file() and p.suffix.lower() in VIDEO_EXTS)
                else:
                    candidates = sorted(p for p in path.iterdir()
                                        if p.is_file() and p.suffix.lower() in IMAGE_EXTS)
                    if not candidates:
                        candidates = sorted(p for p in path.iterdir()
                                            if p.is_file() and p.suffix.lower() in VIDEO_EXTS)
                candidate = candidates[0] if candidates else None
            else:
                # Keep useful type information visible while a typed path is not yet present.
                candidate = path if path.suffix else None
        except OSError:
            candidate = path if path.suffix else None
        suffix = (candidate.suffix if candidate is not None else path.suffix).lower()
        if not suffix:
            return "FOLDER" if path.is_dir() else "—"
        labels = {".jpeg": "JPEG", ".jpg": "JPG", ".tif": "TIFF", ".tiff": "TIFF"}
        return labels.get(suffix, suffix.lstrip(".").upper())

    def _update_preview_input_format(self) -> None:
        """Refresh the compact source-format label without touching preview processing."""
        label = getattr(self, "l_pv_input_format", None)
        if label is None:
            return
        try:
            media_type = self._input_format_label()
            label.configure(text=media_type)
            label.configure(text_color=TEXT)
        except Exception:
            pass

    def _layout_preview_view_row(self, event=None) -> None:
        """Keep all viewing controls on one horizontal line and distribute them across the row."""
        try:
            row = getattr(self, "_preview_view_row", None)
            left = getattr(self, "_view_options_frame", None)
            bg = getattr(self, "_view_background_frame", None)
            if row is None or left is None or bg is None:
                return

            width = int(getattr(event, "width", row.winfo_width()))
            if width <= 1:
                width = row.winfo_width()
            if width <= 1:
                self.after(100, self._layout_preview_view_row)
                return

            # A single straight row is preferred at normal Preview widths (about 500 px).
            # Compact only the fixed-width dropdowns on smaller panes; keep the three
            # viewing-mode segments wide enough that “Side by side” remains readable.
            if width >= 470:
                cmp_width, bg_button_width, bg_menu_width = 56, 66, 88
            elif width >= 420:
                cmp_width, bg_button_width, bg_menu_width = 52, 60, 82
            else:
                cmp_width, bg_button_width, bg_menu_width = 46, 54, 72

            self.opt_cmp.configure(width=cmp_width)
            self.b_bg_choose.configure(width=bg_button_width)
            self.opt_preview_background.configure(width=bg_menu_width)

            # Fixed widths include the “vs” and “BG” labels and their horizontal padding.
            left_fixed = 8 + 18 + cmp_width
            bg_required = 18 + 4 + bg_button_width + 4 + bg_menu_width
            row_gap = 6
            minimum_mode_width = len(VIEW_MODES) * 48
            mode_width = width - left_fixed - bg_required - row_gap

            # The regular Preview panel is wide enough for a single line. If the user
            # narrows the panel unusually far, compress all controls while retaining one
            # line rather than moving the BG controls onto a second row.
            if mode_width < minimum_mode_width:
                deficit = minimum_mode_width - mode_width
                shrink_cmp = min(deficit // 3, max(0, cmp_width - 42))
                cmp_width -= shrink_cmp
                deficit -= shrink_cmp
                shrink_bg_button = min(deficit // 2, max(0, bg_button_width - 48))
                bg_button_width -= shrink_bg_button
                deficit -= shrink_bg_button
                shrink_bg_menu = min(deficit, max(0, bg_menu_width - 64))
                bg_menu_width -= shrink_bg_menu
                self.opt_cmp.configure(width=cmp_width)
                self.b_bg_choose.configure(width=bg_button_width)
                self.opt_preview_background.configure(width=bg_menu_width)
                left_fixed = 8 + 18 + cmp_width
                bg_required = 18 + 4 + bg_button_width + 4 + bg_menu_width
                mode_width = max(minimum_mode_width, width - left_fixed - bg_required - row_gap)

            # Column 1 absorbs the last few pixels; anchoring the BG group to its east
            # edge removes the empty tail seen in the reference screenshot.
            row.grid_columnconfigure(0, weight=0)
            row.grid_columnconfigure(1, weight=1)
            left.grid_configure(row=0, column=0, sticky="w")
            bg.grid_configure(row=0, column=1, sticky="e", padx=(row_gap, 0), pady=0)
            self.seg_view.set_width(int(mode_width))
        except Exception:
            # Geometry changes shouldn't disrupt preview rendering or playback.
            pass

    def _on_input_tagging_preference_changed(self) -> None:
        """Persist EXR tagging state and show/hide its inline Preview hint."""
        enabled = bool(self.v_input_tagging.get())
        self._preferences["input_tagging_enabled"] = enabled
        self._fit_key = None
        try:
            self._flat_image_cache.clear()
        except Exception:
            pass
        self._save_preferences_file()
        self._update_input_tagging_preview()
        if hasattr(self, "pv_label") and self.v_preview_on.get():
            self._pv_request()

    def _sony_lut_status_text(self) -> str:
        root = _sony_lut_library_root()
        files = _sony_lut_library_files()
        def source_token(p):
            return _normalise_lut_name(p.name).split("to", 1)[0]
        slog3_cine = [p for p in files if "slog3" in source_token(p) and "sgamut3cine" in source_token(p)]
        slog3 = [p for p in files if "slog3" in source_token(p) and "sgamut3" in source_token(p) and "sgamut3cine" not in source_token(p)]
        slog2 = [p for p in files if "slog2" in source_token(p) and ("sgamut" in source_token(p) or "sgumut" in source_token(p))]
        selected = str(self.v_sony_lut_look.get()) if getattr(self, "v_sony_lut_look", None) is not None else _SONY_LUT_PREFERRED_LOOK
        profile_mode = str(self.v_sony_lut_profile.get()) if getattr(self, "v_sony_lut_profile", None) is not None else _SONY_LUT_PROFILE_OVERRIDE
        return (f"Library: {root}  ·  {len(files)} CUBE LUT(s)  ·  S-Log2: {len(slog2)}  ·  "
                f"S-Log3/S-Gamut3.Cine: {len(slog3_cine)}  ·  S-Log3/S-Gamut3: {len(slog3)}  ·  "
                f"Input profile: {profile_mode}  ·  Look: {selected}")

    def _apply_sony_lut_preferences(self, announce: bool = True) -> bool:
        """Validate Sony LUT settings, refresh the library/cache and reload Input preview."""
        global _SONY_LUT_CUSTOM_ROOT, _SONY_LUT_ENABLED, _SONY_LUT_AUTO_DETECT
        global _SONY_LUT_PREFERRED_LOOK, _SONY_LUT_PROFILE_OVERRIDE, _SONY_LUT_LIBRARY_SIGNATURE_CACHE
        try:
            path_text = self.pref_sony_lut_path_entry.get().strip()
        except Exception:
            path_text = str(self.v_sony_lut_dir.get())
        path = Path(path_text).expanduser() if path_text else (ROOT / "resources" / "luts" / "sony")
        if not path.is_absolute():
            path = ROOT / path
        try:
            path = path.resolve()
            path.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            messagebox.showerror("Sony LUT library", f"Cannot use this LUT folder:\n{exc}", parent=self._preferences_window or self)
            return False

        _SONY_LUT_CUSTOM_ROOT = path
        _SONY_LUT_ENABLED = bool(self.v_sony_lut_enabled.get())
        _SONY_LUT_AUTO_DETECT = bool(self.v_sony_lut_auto_detect.get())
        _SONY_LUT_PREFERRED_LOOK = str(self.v_sony_lut_look.get() or "Auto (recommended)")
        _SONY_LUT_PROFILE_OVERRIDE = str(self.v_sony_lut_profile.get() or "Auto detect (metadata)")
        _SONY_LUT_LIBRARY_SIGNATURE_CACHE = None
        with _SONY_LUT_LOCK:
            _SONY_LUT_RESOLVE_CACHE.clear()
        with _VIDEO_COLOR_META_LOCK:
            _VIDEO_COLOR_META_CACHE.clear()
        with _PREVIEW_MEMORY_LOCK:
            _PREVIEW_MEMORY_CACHE.clear()
            global _PREVIEW_MEMORY_BYTES
            _PREVIEW_MEMORY_BYTES = 0
        self.v_sony_lut_dir.set(str(path))
        self._preferences["sony_lut_dir"] = str(path)
        self._save_preferences_file()
        status = self._sony_lut_status_text()
        if getattr(self, "pref_sony_lut_status", None) is not None:
            self.pref_sony_lut_status.configure(text=status)
        if announce:
            self._append(f"[Sony LUT] Preferences applied. Enabled={_SONY_LUT_ENABLED}; auto-detect={_SONY_LUT_AUTO_DETECT}; input-profile={_SONY_LUT_PROFILE_OVERRIDE}; look={_SONY_LUT_PREFERRED_LOOK}. {status}", tag="ok")
        if hasattr(self, "pv_label"):
            self._pv_request()
        return True

    def _open_project_folder(self):
        try:
            if os.name == "nt":
                os.startfile(str(ROOT))
            elif sys.platform == "darwin":
                subprocess.Popen(["open", str(ROOT)])
            else:
                subprocess.Popen(["xdg-open", str(ROOT)])
        except Exception as exc:
            messagebox.showerror("Project folder", f"Could not open project folder:\n{exc}", parent=self._preferences_window or self)

    def _launch_sony_lut_installer(self):
        """Run the project Sony LUT BAT directly; never open File Explorer."""
        if os.name != "nt":
            messagebox.showinfo(
                "Sony LUT installer",
                "The automatic Sony LUT BAT installer is supported on Windows.",
                parent=self._preferences_window or self)
            return

        if getattr(self, "_sony_lut_install_running", False):
            self._append("[Sony LUT] Installer is already running.", tag="dim")
            return

        installer = ROOT / "Install_Sony_LUTs.bat"
        if not installer.is_file():
            # Accept the numbered filename Windows may create after repeated downloads.
            candidates = sorted(ROOT.glob("Install_Sony_LUTs*.bat"))
            installer = next((p for p in candidates if p.is_file()), installer)

        downloader = ROOT / "sony_lut_download.py"
        if not installer.is_file() or not downloader.is_file():
            missing = []
            if not installer.is_file():
                missing.append("Install_Sony_LUTs.bat")
            if not downloader.is_file():
                missing.append("sony_lut_download.py")
            messagebox.showerror(
                "Sony LUT installer files missing",
                "The following file(s) must be in the main CorridorKey project folder:\n\n"
                + "\n".join(missing)
                + f"\n\nProject folder:\n{ROOT}",
                parent=self._preferences_window or self)
            return

        try:
            destination = ROOT / "resources" / "luts" / "sony"
            destination.mkdir(parents=True, exist_ok=True)
            (ROOT / "logs").mkdir(parents=True, exist_ok=True)

            # Tell the BAT it was started by the GUI so it does not wait on a
            # hidden PAUSE prompt at the end. CREATE_NO_WINDOW keeps the workflow
            # inside CorridorKey; no console or Explorer window is opened.
            env = os.environ.copy()
            env["CORRIDORKEY_GUI_LAUNCH"] = "1"
            comspec = os.environ.get("COMSPEC", "cmd.exe")
            process = subprocess.Popen(
                [comspec, "/d", "/c", "call", str(installer)],
                cwd=str(ROOT),
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="replace",
                bufsize=1,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            self._sony_lut_install_running = True
            self._sony_lut_install_process = process
            if getattr(self, "pref_sony_lut_status", None) is not None:
                self.pref_sony_lut_status.configure(
                    text=f"Installing official Sony LUTs…  Destination: {destination}")

            self._append(
                f"[Sony LUT] Started {installer.name} automatically in the background. "
                "No folder, browser, or file picker will open.",
                tag="ok")

            def _read_installer_output():
                try:
                    if process.stdout is not None:
                        for raw_line in process.stdout:
                            line = raw_line.rstrip("\r\n")
                            if line:
                                self.msgs.put(("line", f"[Sony LUT installer] {line}", "dim"))
                    return_code = process.wait()
                except Exception as worker_exc:
                    self.msgs.put(("line",
                                   f"[Sony LUT installer] Worker error: {type(worker_exc).__name__}: {worker_exc}",
                                   "err"))
                    return_code = 1
                self.msgs.put(("sony_install_done", return_code, str(installer)))

            threading.Thread(
                target=_read_installer_output,
                name="CorridorKeySonyLUTInstaller",
                daemon=True,
            ).start()

        except Exception as exc:
            self._sony_lut_install_running = False
            self._append_detailed_error(
                "Launch Sony LUT BAT", exc, traceback.format_exc(),
                extra=f"Installer={installer}")
            messagebox.showerror(
                "Sony LUT installer", str(exc),
                parent=self._preferences_window or self)

    def _on_sony_lut_install_finished(self, return_code: int, installer_path: str = ""):
        """Refresh LUT lookup/cache after the BAT installer exits."""
        self._sony_lut_install_running = False
        self._sony_lut_install_process = None

        log_path = ROOT / "logs" / "sony_lut_install.log"
        if return_code == 0:
            self._append("[Sony LUT] Automatic installation completed successfully.", tag="ok")
            try:
                self._apply_sony_lut_preferences(announce=False)
                status = self._sony_lut_status_text()
                if getattr(self, "pref_sony_lut_status", None) is not None:
                    self.pref_sony_lut_status.configure(text=status)
                self._append(f"[Sony LUT] Library refreshed. {status}", tag="ok")
            except Exception as exc:
                self._append_detailed_error(
                    "Refresh Sony LUT library", exc, traceback.format_exc(),
                    extra=f"Installer={installer_path}")
        else:
            message = (f"[Sony LUT] Installer failed with exit code {return_code}. "
                       f"Check {log_path} for the download/extraction error.")
            self._append(message, tag="err")
            if getattr(self, "pref_sony_lut_status", None) is not None:
                self.pref_sony_lut_status.configure(
                    text=f"Installation failed (exit {return_code}). See {log_path}")
    def _browse_sony_lut_folder(self):
        current = self.v_sony_lut_dir.get() if getattr(self, "v_sony_lut_dir", None) is not None else str(_sony_lut_library_root())
        selected = filedialog.askdirectory(parent=self._preferences_window or self,
                                           title="Choose Sony LUT library folder",
                                           initialdir=current if Path(current).is_dir() else str(ROOT))
        if selected:
            self.pref_sony_lut_path_entry.delete(0, "end")
            self.pref_sony_lut_path_entry.insert(0, selected)

    def _on_portable_paths_changed(self):
        self._preferences["portable_paths"] = bool(self.v_portable_paths.get())
        self._save_preferences_file()
        if getattr(self, "pref_portable_status", None) is not None:
            state = "ON" if self.v_portable_paths.get() else "OFF"
            self.pref_portable_status.configure(text=f"Project folder (auto-detected): {ROOT}  ·  Portable paths: {state}")

    def _update_input_tagging_preview(self) -> None:
        """Input tagging is internal; never display tag details in the Preview tab."""
        return

    def _sync_ocio_view_widgets(self):
        """Keep the automatic OCIO view fixed to the config's default display/view."""
        choices = self._ocio_view_choices or [OCIO_UNAVAILABLE_LABEL]
        selected = self._ocio_default_view if self._ocio_default_view in choices else choices[0]
        try:
            if self.v_ocio_view.get() != selected:
                self.v_ocio_view.set(selected)
        except Exception:
            pass

    def _browse_ocio_config(self):
        filename = filedialog.askopenfilename(
            parent=self._preferences_window or self, title="Choose OpenColorIO config",
            filetypes=[("OCIO config", "*.ocio"), ("All files", "*.*")])
        if filename and getattr(self, "pref_ocio_path_entry", None) is not None:
            self.pref_ocio_path_entry.delete(0, "end")
            self.pref_ocio_path_entry.insert(0, filename)

    def _use_aces_ocio_builtin(self):
        if getattr(self, "pref_ocio_path_entry", None) is not None:
            self.pref_ocio_path_entry.delete(0, "end")
            self.pref_ocio_path_entry.insert(0, OCIO_DEFAULT_CONFIG)
        self._apply_ocio_config()

    def _apply_ocio_config(self):
        value = OCIO_DEFAULT_CONFIG
        try:
            value = self.pref_ocio_path_entry.get().strip() or OCIO_DEFAULT_CONFIG
        except Exception:
            pass
        # Normalize relative paths against the app folder so they survive a move
        # to another drive/computer and do not depend on the BAT Start-in folder.
        value = _ocio_normalize_config_path(value)
        # Reload a local config if it was replaced on disk between applies.
        with _OCIO_CONFIG_CACHE_LOCK:
            _OCIO_CONFIG_CACHE.pop(value, None)
        choices, mapping, colors, default_view, status = _ocio_config_metadata(value)
        if HAVE_OCIO and not choices:
            messagebox.showerror("OpenColorIO config", status or "No display/view options were found.",
                                 parent=self._preferences_window or self)
            try:
                self.pref_ocio_status.configure(text=status, text_color=RED)
            except Exception:
                pass
            return
        self._ocio_config_path = value
        # Clear cached processors so a reloaded/overwritten local config takes effect.
        with _OCIO_PROCESSOR_CACHE_LOCK:
            _OCIO_PROCESSOR_CACHE.clear()
        self._ocio_view_choices = choices or [OCIO_UNAVAILABLE_LABEL]
        self._ocio_view_map = mapping
        self._ocio_color_spaces = colors
        self._ocio_default_view = default_view or self._ocio_view_choices[0]
        self._ocio_status = status if HAVE_OCIO else (
            "OpenColorIO binding is not installed. Run: python -m pip install \"opencolorio>=2.5\". "
            "The ACES CG built-in config is provided by OCIO 2.5+.")
        # Use the configuration's default view automatically in every preview.
        self.v_ocio_view.set(self._ocio_default_view)
        if self._ocio_color_spaces:
            colors_cf = {str(name).casefold(): str(name) for name in self._ocio_color_spaces}
            auto_exr_fallback = (colors_cf.get("acescg") or colors_cf.get("aces2065-1")
                                 or colors_cf.get("linear rec.709") or self._ocio_color_spaces[0])
            self.v_ocio_exr_input.set(auto_exr_fallback)
        self._preferences["ocio_config_path"] = value
        self._sync_ocio_view_widgets()
        self._update_input_tagging_preview()
        try:
            self.pref_ocio_status.configure(text=self._ocio_status, text_color=SUCCESS if HAVE_OCIO and mapping else SUBTLE)
        except Exception:
            pass
        self._save_preferences_file()
        self._history_changed()
        self._fit_key = None
        self._preview_color_changed()
        self._update_fullscreen_preview()
        self._update_detached_preview()
        self._append(f"[OCIO] {self._ocio_status}", tag="ok" if HAVE_OCIO and mapping else "dim")

    def _on_ocio_exr_input_changed(self):
        self._preferences["ocio_exr_input"] = self.v_ocio_exr_input.get()
        self._save_preferences_file()
        self._update_input_tagging_preview()
        self._history_changed()
        self._fit_key = None
        self._preview_color_changed()
        self._update_fullscreen_preview()
        self._update_detached_preview()

    def _preview_color_changed(self):
        # Called by Tk's variable trace on the UI thread; this now selects an OCIO view.
        try:
            if hasattr(self, "_preferences_path") and not getattr(self, "_history_busy", False):
                self._save_preferences_file()
        except Exception:
            pass
        if (hasattr(self, "pv_label") and self.v_preview_on.get()
                and not self._history_busy):
            self._pv_request()

    def _on_preview_background_choice(self, choice: str) -> None:
        if choice == "Custom image" and not self.v_preview_bg_image.get().strip():
            self._choose_preview_bg()
        else:
            self._preview_background_changed()

    def _choose_preview_bg(self) -> None:
        filename = filedialog.askopenfilename(
            parent=self,
            title="Choose preview background image",
            filetypes=[("PNG / JPEG images", "*.png *.jpg *.jpeg *.jpe"),
                       ("PNG images", "*.png"), ("JPEG images", "*.jpg *.jpeg *.jpe"),
                       ("All files", "*.*")],
        )
        if not filename:
            if not self.v_preview_bg_image.get().strip():
                self.v_preview_background.set("Checkerboard")
            return
        try:
            with Image.open(filename) as opened:
                opened.verify()
        except Exception as exc:
            messagebox.showerror("Preview background", f"The selected file is not a readable image.\n\n{exc}", parent=self)
            return
        self.v_preview_bg_image.set(filename)
        self._preview_bg_cache_key = None
        self.v_preview_background.set("Custom image")
        # Record the selected image even when the dropdown was already Custom image.
        self._history_changed()
        self._preview_background_changed()

    def _load_custom_preview_bg(self, size: tuple[int, int]) -> Image.Image | None:
        """Load a custom PNG/JPG once, then crop-to-fill the displayed frame."""
        raw_path = self.v_preview_bg_image.get().strip() if hasattr(self, "v_preview_bg_image") else ""
        if not raw_path:
            return None
        try:
            path = Path(raw_path)
            if not path.is_file():
                return None
            stat = path.stat()
            key = (str(path.resolve()), stat.st_mtime_ns, stat.st_size)
            if self._preview_bg_cache_key != key or self._preview_bg_cache_image is None:
                with Image.open(path) as opened:
                    bg = ImageOps.exif_transpose(opened).convert("RGBA")
                self._preview_bg_cache_image = bg.copy()
                self._preview_bg_cache_key = key
            bg = ImageOps.fit(self._preview_bg_cache_image, size, method=Image.LANCZOS,
                              centering=(0.5, 0.5)).convert("RGBA")
            if bg.getchannel("A").getextrema()[0] < 255:
                base = checker_bg(size).convert("RGBA")
                base.alpha_composite(bg)
                bg = base
            return bg
        except Exception:
            return None

    def _preview_background_changed(self):
        # Recompose alpha previews over the chosen background without re-decoding clips.
        try:
            self._flat_image_cache.clear()
        except Exception:
            pass
        self._fit_key = None
        if self.v_preview_background.get() != "Custom image":
            self._preview_bg_cache_key = None
        if hasattr(self, "pv_label") and self.v_preview_on.get():
            self._pv_show(animate=False)
        self._update_fullscreen_preview()
        self._update_detached_preview()

    def _show_first_run_tour_if_needed(self) -> None:
        """Show the welcome guide once, after a successful first GUI launch."""
        if getattr(self, "_closing", False):
            return
        if not bool(self._preferences.get("first_run_tour_completed", False)):
            self._show_feature_tour(first_run=True)

    def _finish_feature_tour(self) -> None:
        self._preferences["first_run_tour_completed"] = True
        self._save_preferences_file()
        self._close_feature_tour()

    def _close_feature_tour(self) -> None:
        win = getattr(self, "_feature_tour_window", None)
        self._feature_tour_window = None
        if win is not None:
            try:
                if win.winfo_exists():
                    win.grab_release()
                    win.destroy()
            except Exception:
                pass

