    def _photocraft_set_status(self, text: str, color=None) -> None:
        try:
            self.photocraft_status_label.configure(text=str(text).upper(),
                                                   text_color=color or SUBTLE)
        except Exception:
            pass

    def _photocraft_find_executable(self) -> Path | None:
        """Resolve a saved or project-local PhotoCraft binary without guessing paths."""
        candidates = []
        saved = str(self._preferences.get("photocraft_exe", "") or "").strip()
        if saved:
            saved_path = Path(os.path.expandvars(os.path.expanduser(saved)))
            if not saved_path.is_absolute():
                saved_path = ROOT / saved_path
            candidates.append(saved_path)
        candidates.extend([
            ROOT / "PhotoCraft.exe",
            ROOT / "photocraft.exe",
            ROOT / "third_party" / "photocraft-source" / "photocraft-main" / "target" / "release" / "photocraft.exe",
            ROOT / "third_party" / "photocraft-source" / "photocraft-main" / "target" / "release" / "photocraft",
            ROOT / "third_party" / "photocraft-portable" / "photocraft.exe",
        ])
        located = shutil.which("photocraft.exe") or shutil.which("photocraft")
        if located:
            candidates.append(Path(located))
        for candidate in candidates:
            try:
                if candidate.is_file():
                    return candidate.resolve()
            except OSError:
                continue
        return None

    def _photocraft_find_cli_executable(self) -> Path | None:
        """Find the PhotoCraft CLI shipped beside the official desktop portable app."""
        candidates = []
        app = self._photocraft_find_executable()
        if app is not None:
            candidates.extend((app.parent / "photocraft-cli.exe", app.parent / "photocraft-cli"))
        candidates.extend((
            ROOT / "photocraft-cli.exe",
            ROOT / "third_party" / "photocraft-portable" / "photocraft-cli.exe",
        ))
        located = shutil.which("photocraft-cli.exe") or shutil.which("photocraft-cli")
        if located:
            candidates.append(Path(located))
        for candidate in candidates:
            try:
                if candidate.is_file():
                    return candidate.resolve()
            except OSError:
                continue
        return None

    def _photocraft_refresh_workspace(self) -> None:
        """Refresh the host status whenever its full-body page is selected."""
        proc = getattr(self, "_photocraft_process", None)
        if proc is not None and proc.poll() is not None:
            self._photocraft_process = None
            self._photocraft_hwnd = None
            self._photocraft_embedded = False
            self._photocraft_set_status("EDITOR CLOSED")
            try:
                self.photocraft_placeholder.grid()
            except Exception:
                pass
        if not self._photocraft_process:
            exe = self._photocraft_find_executable()
            self._photocraft_set_status("READY · APP FOUND" if exe else "READY · APP NOT FOUND")
        elif (self._photocraft_process.poll() is None and self._photocraft_hwnd
              and not self._photocraft_embedded):
            # If the user left PhotoCraft detached, switching back to its workspace
            # attaches the still-running editor to the newly-created host panel.
            self.after_idle(lambda: self._photocraft_set_embedded(True))

    def _photocraft_locate_exe(self) -> None:
        """Let the user select an already installed PhotoCraft executable."""
        path = filedialog.askopenfilename(
            parent=self, title="Locate PhotoCraft executable",
            filetypes=[("PhotoCraft application", "photocraft.exe"), ("Windows applications", "*.exe"), ("All files", "*.*")])
        if not path:
            return
        self._preferences["photocraft_exe"] = str(Path(path).resolve())
        self._save_preferences_file()
        self._photocraft_set_status("APP PATH SAVED", ACCENT)
        try:
            self.photocraft_placeholder_message.configure(
                text="PhotoCraft executable found. Click Launch Editor to open the full editor here.")
        except Exception:
            pass

    def _photocraft_append_build_log(self, line: str) -> None:
        try:
            self.photocraft_build_log.configure(state="normal")
            self.photocraft_build_log.insert("end", str(line))
            self.photocraft_build_log.see("end")
            self.photocraft_build_log.configure(state="disabled")
        except Exception:
            pass

    def _photocraft_download_official(self) -> None:
        """Download and install the signed official Windows portable release."""
        if self._photocraft_downloading or self._photocraft_building:
            return
        if os.name != "nt":
            messagebox.showinfo(
                "Windows build required",
                "This CorridorKey integration currently hosts the Windows PhotoCraft desktop build. "
                "Use the official PhotoCraft website for other operating systems.", parent=self)
            return
        self._photocraft_downloading = True
        try:
            self.b_photocraft_download.configure(state="disabled", text="Downloading…")
            self.b_photocraft_build.configure(state="disabled")
            self.photocraft_build_log.grid()
            self.photocraft_build_log.configure(state="normal")
            self.photocraft_build_log.delete("1.0", "end")
            self.photocraft_build_log.configure(state="disabled")
        except Exception:
            pass
        self._photocraft_set_status("DOWNLOADING OFFICIAL PHOTOCRAFT", ORANGE)
        self._photocraft_append_build_log(
            "Checking the official PhotoCraft GitHub release…\n"
            "The portable Windows package is downloaded directly from the publisher.\n")
        threading.Thread(
            target=self._photocraft_download_worker,
            name="CorridorKeyPhotoCraftDownload", daemon=True).start()

    def _photocraft_download_worker(self) -> None:
        """Fetch latest official portable build, validate it, and install it locally."""
        download_path = None
        extract_dir = None
        try:
            api_url = "https://api.github.com/repos/storytold/photocraft/releases/latest"
            request = urllib.request.Request(
                api_url,
                headers={"User-Agent": "CorridorKey-PhotoCraft-Installer/1.0",
                         "Accept": "application/vnd.github+json"})
            with urllib.request.urlopen(request, timeout=30) as response:
                release = json.loads(response.read(5 * 1024 * 1024).decode("utf-8"))

            tag = str(release.get("tag_name") or "latest")
            safe_tag = re.sub(r"[^A-Za-z0-9._-]+", "_", tag).strip("._") or "latest"
            machine = (platform.machine() or os.environ.get("PROCESSOR_ARCHITECTURE", "")).lower()
            if "arm64" in machine or "aarch64" in machine:
                arch = "arm64"
            elif machine in ("x86", "i386", "i486", "i586", "i686"):
                arch = "x86"
            else:
                arch = "x64"

            assets = release.get("assets") or []
            suffix = f"windows-{arch}-portable.zip"
            asset = next((item for item in assets
                          if str(item.get("name", "")).lower().endswith(suffix)), None)
            if asset is None and arch != "x64":
                raise RuntimeError(
                    f"The latest official release has no Windows {arch} portable package. "
                    "Download the matching installer from https://github.com/storytold/photocraft/releases.")
            if asset is None:
                raise RuntimeError(
                    "The latest official release did not list a Windows x64 portable ZIP. "
                    "Open https://github.com/storytold/photocraft/releases and use Locate EXE after installation.")

            asset_name = str(asset.get("name") or f"photocraft-{safe_tag}-{suffix}")
            asset_url = str(asset.get("browser_download_url") or "")
            if not asset_url.startswith("https://github.com/storytold/photocraft/releases/download/"):
                raise RuntimeError("GitHub returned an unexpected PhotoCraft download URL.")

            third_party = ROOT / "third_party"
            third_party.mkdir(parents=True, exist_ok=True)
            install_dir = third_party / f"photocraft-{safe_tag}-windows-{arch}-portable"
            exe_name = "photocraft.exe"
            existing = next((path for path in install_dir.rglob(exe_name) if path.is_file()), None) if install_dir.is_dir() else None
            if existing is not None:
                self.after(0, self._photocraft_download_completed, str(existing), tag, "")
                return

            downloads_dir = third_party / "downloads"
            downloads_dir.mkdir(parents=True, exist_ok=True)
            download_path = downloads_dir / asset_name
            partial_path = download_path.with_suffix(download_path.suffix + ".part")
            self.after(0, self._photocraft_append_build_log,
                       f"Release: {tag}\nPackage: {asset_name}\nArchitecture: Windows {arch}\nDownloading portable app…\n")

            digest = hashlib.sha256()
            received = 0
            expected_size = int(asset.get("size") or 0)
            req = urllib.request.Request(
                asset_url, headers={"User-Agent": "CorridorKey-PhotoCraft-Installer/1.0"})
            with urllib.request.urlopen(req, timeout=90) as response, partial_path.open("wb") as output:
                while True:
                    chunk = response.read(1024 * 1024)
                    if not chunk:
                        break
                    output.write(chunk)
                    digest.update(chunk)
                    received += len(chunk)
                    if received % (32 * 1024 * 1024) < len(chunk):
                        mb = received / (1024 * 1024)
                        total = f" / {expected_size / (1024 * 1024):.0f} MB" if expected_size else ""
                        self.after(0, self._photocraft_append_build_log,
                                   f"Downloaded {mb:.0f} MB{total}…\n")
            if expected_size and received != expected_size:
                raise RuntimeError(
                    f"Download size mismatch: expected {expected_size:,} bytes, received {received:,} bytes.")

            actual_sha = digest.hexdigest().lower()
            expected_digest = str(asset.get("digest") or "").lower()
            if expected_digest.startswith("sha256:"):
                expected_digest = expected_digest.split(":", 1)[1]
            # GitHub's release API exposes a per-asset digest on current releases.
            # Fall back to the publisher's SHA256SUMS.txt for older release metadata.
            if not expected_digest:
                sums_asset = next((item for item in assets
                                   if str(item.get("name", "")).casefold() == "sha256sums.txt"), None)
                sums_url = str((sums_asset or {}).get("browser_download_url") or "")
                if sums_url.startswith("https://github.com/storytold/photocraft/releases/download/"):
                    sums_request = urllib.request.Request(
                        sums_url, headers={"User-Agent": "CorridorKey-PhotoCraft-Installer/1.0"})
                    with urllib.request.urlopen(sums_request, timeout=30) as sums_response:
                        sums_text = sums_response.read(2 * 1024 * 1024).decode("utf-8", "replace")
                    for sums_line in sums_text.splitlines():
                        fields = sums_line.strip().split()
                        if len(fields) >= 2 and Path(fields[-1].lstrip("*")).name.casefold() == asset_name.casefold():
                            if re.fullmatch(r"[0-9a-fA-F]{64}", fields[0]):
                                expected_digest = fields[0].lower()
                                break
            if expected_digest and actual_sha != expected_digest:
                raise RuntimeError("PhotoCraft download failed its SHA-256 checksum check.")
            partial_path.replace(download_path)

            if not zipfile.is_zipfile(download_path):
                raise RuntimeError("The official PhotoCraft download is not a valid ZIP archive.")
            if install_dir.exists():
                # This path is dedicated to this exact publisher/release/architecture.
                shutil.rmtree(install_dir)
            extract_dir = third_party / f".photocraft-{safe_tag}-{arch}.extracting"
            if extract_dir.exists():
                shutil.rmtree(extract_dir)
            extract_dir.mkdir(parents=True, exist_ok=True)
            base = extract_dir.resolve()
            with zipfile.ZipFile(download_path, "r") as zf:
                bad_member = zf.testzip()
                if bad_member:
                    raise RuntimeError(f"PhotoCraft ZIP failed its CRC check: {bad_member}")
                for member in zf.infolist():
                    target = (extract_dir / member.filename).resolve()
                    if target != base and base not in target.parents:
                        raise RuntimeError(f"Unsafe path in PhotoCraft archive: {member.filename}")
                zf.extractall(extract_dir)

            exe_in_temp = next((path for path in extract_dir.rglob("*")
                                if path.is_file() and path.name.lower() == exe_name), None)
            if exe_in_temp is None:
                raise RuntimeError("PhotoCraft ZIP extracted, but photocraft.exe was not present.")
            os.replace(extract_dir, install_dir)
            extract_dir = None
            exe_path = install_dir / exe_in_temp.relative_to(base)
            try:
                download_path.unlink()
            except OSError:
                pass
            self.after(0, self._photocraft_download_completed, str(exe_path), tag, "")
        except Exception as exc:
            try:
                self.after(0, self._photocraft_download_completed, "", "", str(exc))
            except Exception:
                pass
        finally:
            if download_path is not None:
                try:
                    partial = download_path.with_suffix(download_path.suffix + ".part")
                    if partial.exists():
                        partial.unlink()
                except OSError:
                    pass
            if extract_dir is not None and extract_dir.exists():
                try:
                    shutil.rmtree(extract_dir)
                except OSError:
                    pass

    def _photocraft_download_completed(self, exe_path: str, release_tag: str, error: str) -> None:
        """Return download/install result to the Tk thread."""
        self._photocraft_downloading = False
        try:
            self.b_photocraft_download.configure(state="normal", text="Install / Update")
            self.b_photocraft_build.configure(state="normal")
        except Exception:
            pass
        if error:
            self._photocraft_pending_hint_request = None
            self._photocraft_append_build_log("\nINSTALL FAILED: " + error + "\n")
            self._photocraft_set_status("INSTALL FAILED", RED)
            try:
                self.photocraft_placeholder_message.configure(
                    text="PhotoCraft could not be installed automatically. Check the install log, "
                         "or use Locate EXE / Build from Source.")
            except Exception:
                pass
            messagebox.showerror(
                "PhotoCraft installation failed",
                "CorridorKey is still available. The PhotoCraft hint editor could not be installed:\n\n"
                + str(error), parent=self)
            return
        resolved = Path(exe_path).resolve()
        try:
            self._preferences["photocraft_exe"] = resolved.relative_to(ROOT.resolve()).as_posix()
        except ValueError:
            self._preferences["photocraft_exe"] = str(resolved)
        self._save_preferences_file()
        self._photocraft_append_build_log(
            f"\nINSTALL COMPLETE: PhotoCraft {release_tag} is ready.\n{resolved}\n")
        self._photocraft_set_status("PHOTOCRAFT INSTALLED · READY TO LAUNCH", ACCENT)
        try:
            self.photocraft_placeholder_message.configure(
                text=f"PhotoCraft {release_tag} is installed. Click Launch Editor to open the original editor here.")
        except Exception:
            pass
        pending_request = getattr(self, "_photocraft_pending_hint_request", None)
        if pending_request:
            self._photocraft_pending_hint_request = None
            self.after(350, lambda request=pending_request:
                       self._photocraft_edit_hint_variable(**request))
        pending_hint = getattr(self, "_photocraft_pending_open_path", None)
        if pending_hint and Path(pending_hint).is_file():
            self.after(450, self._photocraft_launch, pending_hint)

    def _photocraft_build_from_source(self) -> None:
        """Build the provided Rust source in a worker so CorridorKey stays responsive."""
        if self._photocraft_building or self._photocraft_downloading:
            return
        archive = ROOT / "photocraft-main.zip"
        if not archive.is_file():
            messagebox.showwarning(
                "PhotoCraft source not found",
                "Place the supplied photocraft-main.zip beside corridorkey_gui.py, then try again.",
                parent=self)
            return
        cargo = shutil.which("cargo")
        rustc = shutil.which("rustc")
        if not cargo or not rustc:
            messagebox.showinfo(
                "Rust toolchain required",
                "PhotoCraft is a Rust application. Install the Rust toolchain (Rust 1.95 or newer), "
                "restart CorridorKey, then click Build from Source again.\n\n"
                "Official installer: https://rustup.rs/", parent=self)
            return
        self._photocraft_building = True
        self.b_photocraft_build.configure(state="disabled", text="Building…")
        self.photocraft_build_log.grid()
        self.photocraft_build_log.configure(state="normal")
        self.photocraft_build_log.delete("1.0", "end")
        self.photocraft_build_log.configure(state="disabled")
        self._photocraft_set_status("BUILDING PHOTOCRAFT", ORANGE)
        self._photocraft_append_build_log("Preparing PhotoCraft source…\n")
        threading.Thread(
            target=self._photocraft_build_worker, args=(archive, cargo, rustc),
            name="CorridorKeyPhotoCraftBuild", daemon=True).start()

    def _photocraft_build_worker(self, archive: Path, cargo: str, rustc: str) -> None:
        """Extract safely and compile PhotoCraft; only UI updates are marshalled to Tk."""
        source_root = ROOT / "third_party" / "photocraft-source" / "photocraft-main"
        try:
            version = subprocess.run([rustc, "--version"], capture_output=True, text=True, timeout=20)
            version_text = (version.stdout or version.stderr or "").strip()
            match = re.search(r"rustc (\d+)\.(\d+)", version_text)
            if version.returncode != 0 or not match or (int(match.group(1)), int(match.group(2))) < (1, 95):
                raise RuntimeError(
                    f"PhotoCraft source requires Rust 1.95 or newer. Detected: {version_text or 'unknown'}")
            if not (source_root / "Cargo.toml").is_file():
                extract_dir = source_root.parent
                extract_dir.mkdir(parents=True, exist_ok=True)
                base = extract_dir.resolve()
                with zipfile.ZipFile(archive, "r") as zf:
                    for member in zf.infolist():
                        target = (extract_dir / member.filename).resolve()
                        if target != base and base not in target.parents:
                            raise RuntimeError(f"Unsafe path in PhotoCraft archive: {member.filename}")
                    zf.extractall(extract_dir)
            if not (source_root / "Cargo.toml").is_file():
                raise RuntimeError("The archive did not contain photocraft-main/Cargo.toml.")
            self.after(0, self._photocraft_append_build_log,
                       f"Rust toolchain: {version_text}\nCompiling PhotoCraft (release)…\n")
            command = [cargo, "build", "--release", "--locked", "--package", "photocraft"]
            process = subprocess.Popen(
                command, cwd=str(source_root), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, encoding="utf-8", errors="replace", bufsize=1)
            self._photocraft_build_process = process
            if process.stdout is not None:
                for line in process.stdout:
                    try:
                        self.after(0, self._photocraft_append_build_log, line)
                    except Exception:
                        pass
            return_code = process.wait()
            self._photocraft_build_process = None
            exe = source_root / "target" / "release" / ("photocraft.exe" if os.name == "nt" else "photocraft")
            if return_code != 0:
                raise RuntimeError(f"Cargo build failed with exit code {return_code}.")
            if not exe.is_file():
                raise RuntimeError(f"Cargo finished but the application was not found at {exe}.")
            self.after(0, self._photocraft_build_completed, str(exe), "")
        except Exception as exc:
            self._photocraft_build_process = None
            try:
                self.after(0, self._photocraft_build_completed, "", str(exc))
            except Exception:
                pass

    def _photocraft_build_completed(self, exe_path: str, error: str) -> None:
        self._photocraft_building = False
        try:
            self.b_photocraft_build.configure(state="normal", text="Build from Source")
        except Exception:
            pass
        if error:
            self._photocraft_append_build_log("\nBUILD FAILED: " + error + "\n")
            self._photocraft_set_status("BUILD FAILED", RED)
            return
        self._preferences["photocraft_exe"] = str(Path(exe_path).resolve())
        self._save_preferences_file()
        self._photocraft_append_build_log("\nBUILD COMPLETE: " + exe_path + "\n")
        self._photocraft_set_status("BUILD COMPLETE · READY TO LAUNCH", ACCENT)
        try:
            self.photocraft_placeholder_message.configure(
                text="PhotoCraft is built successfully. Click Launch Editor to open its native interface.")
        except Exception:
            pass

    def _photocraft_launch(self, open_path: str | None = None) -> None:
        """Start PhotoCraft with an optional image, or open a new tab in the running editor."""
        requested_path = str(open_path or self._photocraft_pending_open_path or "").strip()
        if requested_path:
            candidate = Path(requested_path).expanduser()
            if not candidate.is_file():
                messagebox.showwarning(
                    "PhotoCraft hint image missing",
                    f"The image to open no longer exists:\n{candidate}", parent=self)
                return
            requested_path = str(candidate.resolve())

        proc = getattr(self, "_photocraft_process", None)
        if proc is not None and proc.poll() is None:
            if requested_path:
                self._photocraft_open_file_in_running_instance(requested_path)
                self._photocraft_watch_hint_file(requested_path)
            elif self._photocraft_hwnd:
                self._photocraft_focus_editor()
            else:
                self._photocraft_set_status("STARTING PHOTOCRAFT", ORANGE)
            return

        exe = self._photocraft_find_executable()
        if exe is None:
            self._photocraft_set_status("PHOTOCRAFT APP NOT INSTALLED", RED)
            install_now = messagebox.askyesno(
                "PhotoCraft is not installed",
                "Download and install the official signed Windows PhotoCraft portable app now?\n\n"
                "This does not require Rust or Cargo. An internet connection is required.",
                parent=self)
            if install_now:
                self._photocraft_pending_open_path = requested_path or None
                self._photocraft_download_official()
            else:
                self._photocraft_pending_open_path = None
            return
        try:
            args = [str(exe), "--new-instance"]
            if os.name == "nt":
                args.append("--in-window-menus")
            if requested_path:
                args.append(requested_path)
            self._photocraft_process = subprocess.Popen(
                args, cwd=str(exe.parent), stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                close_fds=(os.name != "nt"))
            self._photocraft_pending_open_path = None
            if requested_path:
                self._photocraft_watch_hint_file(requested_path)
            self._photocraft_set_status("STARTING PHOTOCRAFT", ORANGE)
            try:
                self.photocraft_placeholder.grid_remove()
            except Exception:
                pass
            self._photocraft_poll_window(time.monotonic() + 25.0)
        except Exception as exc:
            self._photocraft_process = None
            self._photocraft_set_status("LAUNCH FAILED", RED)
            messagebox.showerror("PhotoCraft launch failed", str(exc), parent=self)

    def _photocraft_open_file_in_running_instance(self, image_path: str) -> None:
        """Use PhotoCraft's documented file argument to open a new tab in its live instance."""
        exe = self._photocraft_find_executable()
        if exe is None:
            self._photocraft_set_status("PHOTOCRAFT APP NOT FOUND", RED)
            return
        try:
            subprocess.Popen(
                [str(exe), str(Path(image_path).resolve())], cwd=str(exe.parent),
                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL, close_fds=(os.name != "nt"))
            self.after(220, self._photocraft_focus_editor)
        except Exception as exc:
            self._photocraft_append_build_log(f"Could not send hint image to PhotoCraft: {exc}\n")
            messagebox.showerror("PhotoCraft hand-off failed", str(exc), parent=self)

    def _photocraft_read_still(self, source: Path) -> Image.Image | None:
        """Decode a still image, including EXR, into an RGBA frame for hint creation."""
        suffix = source.suffix.lower()
        if suffix == ".exr" and HAVE_CV:
            try:
                raw = cv2.imread(str(source), cv2.IMREAD_UNCHANGED)
                if raw is None or raw.size == 0:
                    return None
                if raw.ndim == 2:
                    rgb = np.repeat(raw[:, :, None], 3, axis=2)
                    alpha = None
                elif raw.shape[2] == 4:
                    rgb = cv2.cvtColor(raw[:, :, :3], cv2.COLOR_BGR2RGB)
                    alpha = raw[:, :, 3]
                else:
                    rgb = cv2.cvtColor(raw[:, :, :3], cv2.COLOR_BGR2RGB)
                    alpha = None
                if np.issubdtype(rgb.dtype, np.floating):
                    rgb = np.nan_to_num(rgb, nan=0.0, posinf=1.0, neginf=0.0)
                    # EXR hint canvases are display images. Keep the preview bounded and
                    # predictable rather than allowing HDR values to wrap on uint8 cast.
                    rgb = np.clip(rgb, 0.0, 1.0) * 255.0
                else:
                    rgb = np.clip(rgb, 0, 255)
                rgba = np.empty((rgb.shape[0], rgb.shape[1], 4), dtype=np.uint8)
                rgba[:, :, :3] = rgb.astype(np.uint8)
                if alpha is None:
                    rgba[:, :, 3] = 255
                else:
                    if np.issubdtype(alpha.dtype, np.floating):
                        alpha = np.clip(np.nan_to_num(alpha, nan=1.0), 0.0, 1.0) * 255.0
                    rgba[:, :, 3] = np.clip(alpha, 0, 255).astype(np.uint8)
                return Image.fromarray(rgba, "RGBA")
            except Exception:
                return None
        try:
            with Image.open(source) as image:
                return image.convert("RGBA")
        except Exception:
            return None

    def _photocraft_source_frame(self, source_clip: str | None = None) -> Image.Image | None:
        """Decode frame zero from the requested clip; never reuse a possibly stale preview frame."""
        source_text = str(source_clip or "").strip().strip('"')
        if not source_text:
            input_var = getattr(self, "v_input", None)
            source_text = str(input_var.get() if input_var is not None else "").strip().strip('"')
        if not source_text:
            return None
        source = Path(source_text).expanduser()
        if source.is_dir():
            try:
                frame_paths = sorted(
                    (p for p in source.iterdir() if p.is_file() and p.suffix.lower() in IMAGE_EXTS),
                    key=lambda p: p.name.casefold())
            except OSError:
                frame_paths = []
            for frame_path in frame_paths:
                frame = self._photocraft_read_still(frame_path)
                if frame is not None:
                    return frame
            return None
        if not source.is_file():
            return None
        if source.suffix.lower() in IMAGE_EXTS:
            return self._photocraft_read_still(source)
        if source.suffix.lower() in VIDEO_EXTS and HAVE_CV:
            capture = None
            try:
                capture = cv2.VideoCapture(str(source))
                if not capture.isOpened():
                    return None
                capture.set(cv2.CAP_PROP_POS_FRAMES, 0)
                ok, frame = capture.read()
                if not ok or frame is None or frame.size == 0:
                    return None
                if frame.ndim == 2:
                    return Image.fromarray(frame).convert("RGBA")
                if frame.shape[2] == 4:
                    frame = cv2.cvtColor(frame, cv2.COLOR_BGRA2RGBA)
                else:
                    frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
                return Image.fromarray(frame).convert("RGBA")
            except Exception:
                return None
            finally:
                if capture is not None:
                    try:
                        capture.release()
                    except Exception:
                        pass
        return None

    def _photocraft_artifact_paths(self, clip_path: str | Path, owner: str = "main") -> dict[str, Path]:
        """Return separate first-frame, editable PSD and render-hint PNG paths."""
        clip = Path(clip_path).expanduser()
        try:
            identity = str(clip.resolve()).casefold()
        except OSError:
            identity = str(clip.absolute()).casefold()
        identity_hash = hashlib.sha1(identity.encode("utf-8", "replace")).hexdigest()[:8]
        safe_stem = re.sub(r"[^A-Za-z0-9._-]+", "_", clip.stem).strip("._") or "clip"
        safe_owner = re.sub(r"[^A-Za-z0-9._-]+", "_", str(owner)).strip("._") or "main"
        base = f"{safe_stem}_{identity_hash}_{safe_owner}"
        return {
            "first_frame": ROOT / "first_frames" / f"{base}_first.png",
            "psd": ROOT / "photocraft_psd" / f"{base}_hint.psd",
            "png": ROOT / "hint_masks" / f"{base}_hint.png",
        }

    def _photocraft_is_managed_hint_png(self, path_value: str | Path | None) -> bool:
        """Return True for PNG hints generated and managed inside this project."""
        if not path_value:
            return False
        try:
            path = Path(path_value).expanduser().resolve()
            hint_root = (ROOT / "hint_masks").resolve()
            return (path.parent == hint_root and path.suffix.lower() == ".png"
                    and path.stem.casefold().endswith("_hint"))
        except (OSError, TypeError, ValueError):
            return False

    def _photocraft_find_matching_hint_png(
        self, clip_path: str | Path, preferred_path: str | Path | None = None
    ) -> Path | None:
        """Find the PNG hint belonging to this exact source clip, using its filename identity.

        Current PhotoCraft files include both a sanitized clip name and an eight-character
        hash of the resolved source path. This prevents two files with the same basename
        in different folders from sharing a hint. Older un-hashed name-only files are used
        only when there is exactly one unambiguous candidate.
        """
        clip = Path(clip_path).expanduser()
        artifacts = self._photocraft_artifact_paths(clip, "main")
        main_png = artifacts["png"]
        marker = "_main_hint"
        expected_stem = main_png.stem
        identity_prefix = (expected_stem[:-len(marker)] if expected_stem.casefold().endswith(marker)
                           else expected_stem.rsplit("_", 1)[0])
        identity_prefix_cf = (identity_prefix + "_").casefold()
        hint_dir = ROOT / "hint_masks"

        # A queue item may already be linked to a previously-created queue-owned PNG.
        # Accept it only when it carries this clip's exact name+path identity.
        if preferred_path:
            try:
                preferred = Path(preferred_path).expanduser().resolve()
                if (preferred.is_file() and preferred.suffix.lower() == ".png"
                        and preferred.parent == hint_dir.resolve()
                        and preferred.stem.casefold().startswith(identity_prefix_cf)
                        and preferred.stem.casefold().endswith("_hint")):
                    return preferred
            except (OSError, TypeError, ValueError):
                pass

        exact = []
        try:
            if hint_dir.is_dir():
                for candidate in hint_dir.iterdir():
                    stem_cf = candidate.stem.casefold()
                    if (candidate.is_file() and candidate.suffix.lower() == ".png"
                            and stem_cf.startswith(identity_prefix_cf)
                            and stem_cf.endswith("_hint")):
                        try:
                            if candidate.stat().st_size >= 16:
                                exact.append(candidate.resolve())
                        except OSError:
                            continue
        except OSError:
            exact = []

        if exact:
            # Prefer the current stable/main artifact, otherwise the most recently saved
            # queue-owned mask for this exact clip identity.
            if main_png.is_file():
                return main_png.resolve()
            try:
                exact.sort(key=lambda item: item.stat().st_mtime_ns, reverse=True)
            except OSError:
                exact.sort(key=lambda item: item.name.casefold())
            return exact[0]

        # Compatibility with manually named/older masks such as shot01.png,
        # shot01_hint.png or shot01_mask.png. Only choose a loose filename match
        # when unique; never guess between same-basename clips or several variants.
        safe_stem = re.sub(
            r"[^A-Za-z0-9._-]+", "_", clip.stem).strip("._") or "clip"
        accepted_names = {safe_stem.casefold(), safe_stem.casefold() + "_hint",
                          safe_stem.casefold() + "_mask"}
        loose = []
        try:
            if hint_dir.is_dir():
                for candidate in hint_dir.iterdir():
                    name = candidate.stem.casefold()
                    if (candidate.is_file() and candidate.suffix.lower() == ".png"
                            and name in accepted_names):
                        try:
                            if candidate.stat().st_size >= 16:
                                loose.append(candidate.resolve())
                        except OSError:
                            continue
        except OSError:
            loose = []
        if len(loose) != 1:
            return None
        # A legacy filename-only mask is ambiguous when the Media pool contains
        # multiple source clips with the same basename from different folders.
        try:
            same_name_sources = set()
            for media_item in getattr(self, "media", []):
                media_path = Path(media_item.get("key") or "").expanduser()
                if media_path.stem.casefold() == clip.stem.casefold():
                    same_name_sources.add(os.path.normcase(os.path.abspath(str(media_path))))
            if len(same_name_sources) > 1:
                return None
        except Exception:
            pass
        return loose[0]

    def _photocraft_autoload_main_hint(self, source_clip: str | Path | None) -> None:
        """Auto-select a filename-matched PNG hint whenever the main input clip changes."""
        if not source_clip:
            return
        try:
            input_text = str(self.v_input.get() or "").strip().strip('"')
            input_path = Path(input_text).expanduser() if input_text else Path(source_clip)
            # A batch folder contains several clips; one global hint must not be attached
            # to all of them. Queue Studio resolves hints individually per queue item.
            if self.v_batch.get() and input_path.is_dir():
                return
        except Exception:
            pass

        current_hint = str(self.v_hint.get() or "").strip().strip('"')
        matched = self._photocraft_find_matching_hint_png(source_clip)
        if matched is not None:
            matched_text = str(matched.resolve())
            if os.path.normcase(os.path.abspath(current_hint)) != os.path.normcase(matched_text):
                self.v_hint.set(matched_text)
                self._append(
                    f"[Hint Auto-Load] {Path(source_clip).name}: matched {matched.name} by clip filename. "
                    "First-frame hint selected automatically.", tag="ok")
            self._photocraft_auto_hint_path = matched_text
            self._photocraft_auto_hint_clip = str(Path(source_clip).expanduser().resolve())
            if self.v_mode.get() != "first":
                self._on_mode("First frame")
            return

        # Do not leave the previous clip's generated mask attached to the new clip.
        # User-selected hints outside the managed hint_masks folder remain untouched.
        if self._photocraft_is_managed_hint_png(current_hint):
            self.v_hint.set("")
            if self.v_mode.get() == "first":
                self._on_mode("No hint")
            self._photocraft_auto_hint_path = ""
            self._photocraft_auto_hint_clip = str(Path(source_clip).expanduser().resolve())
            self._append(
                f"[Hint Auto-Load] No filename-matched PNG found for {Path(source_clip).name}; "
                "cleared the previous clip's managed hint.", tag="dim")

    def _photocraft_autoload_queue_hint(self, item: dict, *, rebuild: bool = True) -> bool:
        """Attach an existing matching PNG to one queue item and rebuild its command."""
        clip = Path(item.get("clip", ""))
        settings = dict(item.get("settings") or {})
        artifacts = dict(item.get("photocraft_artifacts") or {
            key: str(value) for key, value in self._photocraft_artifact_paths(
                clip, f"queue_{item.get('id', 'unknown')}").items()})
        preferred = artifacts.get("png")
        matched = self._photocraft_find_matching_hint_png(clip, preferred_path=preferred)
        changed = False

        if matched is not None:
            matched_text = str(matched.resolve())
            if str(settings.get("v_hint") or "").strip().strip('"') != matched_text:
                settings["v_hint"] = matched_text
                changed = True
            if settings.get("v_mode") != "first":
                settings["v_mode"] = "first"
                changed = True
            if str(artifacts.get("png", "")) != matched_text:
                artifacts["png"] = matched_text
                changed = True
            # Reuse the PSD master paired with this PNG when present. If it does not
            # exist, PhotoCraft will create a new PSD from this PNG on first edit.
            paired_psd = ROOT / "photocraft_psd" / f"{matched.stem}.psd"
            if paired_psd.is_file() and str(artifacts.get("psd", "")) != str(paired_psd):
                artifacts["psd"] = str(paired_psd)
                changed = True
        else:
            current_hint = str(settings.get("v_hint") or "").strip().strip('"')
            if self._photocraft_is_managed_hint_png(current_hint):
                settings["v_hint"] = ""
                if settings.get("v_mode") == "first":
                    settings["v_mode"] = "none"
                changed = True

        item["settings"] = settings
        item["photocraft_artifacts"] = artifacts
        if changed and rebuild and item.get("status") != "RUNNING":
            cmd, outdir = self._build_cmd(
                clip, unique=True, settings=settings, ignore_qid=item.get("id"))
            item["cmd"] = cmd
            item["outdir"] = outdir
            item["summary"] = self._settings_summary(settings)
        if changed:
            self._append(
                f"[Hint Auto-Load] {clip.name}: "
                + (f"loaded {Path(settings.get('v_hint', '')).name}." if matched else
                   "no matching managed PNG found; cleared the stale hint."),
                tag="ok" if matched else "dim")
        return changed

    def _photocraft_create_first_frame_file(
        self, source_clip: str | Path, target_path: str | Path, *, overwrite: bool = False
    ) -> Path:
        """Extract and store the real first frame in the dedicated first_frames folder."""
        target = Path(target_path).expanduser().resolve()
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.is_file() and not overwrite:
            return target
        frame = self._photocraft_source_frame(str(source_clip))
        if frame is None:
            raise RuntimeError(
                f"Could not decode the first frame from:\n{source_clip}\n\n"
                "For videos, check that OpenCV can read the file. For image sequences, "
                "make sure the folder contains readable PNG, JPG, TIFF or EXR frames.")
        temp = target.with_name(
            target.stem + f".writing_{os.getpid()}_{time.time_ns() % 1_000_000}.png")
        frame.convert("RGBA").save(temp, format="PNG", optimize=True)
        os.replace(temp, target)
        return target

    def _photocraft_cli_convert(self, cli_path: str, source_path: str, output_path: str) -> None:
        """Convert a document through PhotoCraft's own CLI; PSD->PNG is flattened transparently."""
        src = Path(source_path).expanduser().resolve()
        dst = Path(output_path).expanduser().resolve()
        dst.parent.mkdir(parents=True, exist_ok=True)
        result = subprocess.run(
            [str(cli_path), "convert", str(src), str(dst)],
            cwd=str(Path(cli_path).resolve().parent), capture_output=True, text=True,
            timeout=300, check=False)
        if result.returncode != 0:
            details = (result.stderr or result.stdout or "No diagnostic was returned.").strip()
            raise RuntimeError(f"PhotoCraft CLI conversion failed ({result.returncode}):\n{details}")
        if not dst.is_file() or dst.stat().st_size < 16:
            raise RuntimeError(f"PhotoCraft CLI reported success but did not create: {dst}")
        if dst.suffix.lower() == ".png":
            with Image.open(dst) as exported:
                exported.verify()

    def _photocraft_prepare_psd_and_open(
        self, seed_png: Path, psd_path: Path, hint_png: Path
    ) -> None:
        """Create the editable PSD in the background, then open it in PhotoCraft."""
        cli = self._photocraft_find_cli_executable()
        if cli is None:
            messagebox.showerror(
                "PhotoCraft CLI not found",
                "The PhotoCraft desktop app is present, but photocraft-cli.exe is missing.\n\n"
                "Use Install / Update in the PhotoCraft workspace to install the official "
                "portable package (it includes the CLI), then try again.", parent=self)
            self._photocraft_set_status("PHOTOCRAFT CLI REQUIRED", RED)
            return
        temp_psd = psd_path.with_name(
            psd_path.stem + f".creating_{os.getpid()}_{time.time_ns() % 1_000_000}.psd")
        self._photocraft_set_status("CREATING PER-CLIP PSD", ORANGE)
        self._append(
            f"[PhotoCraft] Creating editable PSD: {psd_path.name} from {seed_png.name}…",
            tag="dim")

        def worker():
            error = ""
            try:
                temp_psd.parent.mkdir(parents=True, exist_ok=True)
                try:
                    temp_psd.unlink()
                except FileNotFoundError:
                    pass
                self._photocraft_cli_convert(str(cli), str(seed_png), str(temp_psd))
                os.replace(temp_psd, psd_path)
            except Exception as exc:
                error = str(exc)
                try:
                    temp_psd.unlink()
                except OSError:
                    pass
            try:
                self.after(0, self._photocraft_psd_prepared, str(psd_path), str(hint_png), error)
            except Exception:
                pass

        threading.Thread(target=worker, name="CorridorKeyPhotoCraftPSD", daemon=True).start()

    def _photocraft_psd_prepared(self, psd_path: str, hint_png: str, error: str = "") -> None:
        """Finish PSD preparation on the Tk thread and launch the native editor."""
        if error:
            self._photocraft_set_status("PSD CREATION FAILED", RED)
            self._append(f"[PhotoCraft] PSD creation failed: {error}\n", tag="err")
            messagebox.showerror("Could not create editable PSD", error, parent=self)
            return
        psd = str(Path(psd_path).resolve())
        png = str(Path(hint_png).resolve())
        self._photocraft_hint_export_targets[psd] = png
        self._append(
            f"[PhotoCraft] Editable PSD ready: {Path(psd).name}. Save this PSD with Ctrl+S; "
            f"CorridorKey will automatically export and replace {Path(png).name}.", tag="ok")
        self._photocraft_launch(open_path=psd)

    def _photocraft_edit_hint_variable(
        self, hint_var, mode_var=None, mode_value="First frame", *,
        source_clip: str | None = None, parent=None, force_current_frame: bool = False,
        dedicated_path: str | Path | None = None,
        first_frame_path: str | Path | None = None,
        psd_path: str | Path | None = None,
    ) -> None:
        """Create per-clip first-frame/PSD/PNG assets and open the layered PSD."""
        parent = parent or self

        # PhotoCraft is an optional companion app, not a CorridorKey workspace.
        # Install its official portable bundle (desktop app + CLI) on first hint use.
        if self._photocraft_find_executable() is None or self._photocraft_find_cli_executable() is None:
            if getattr(self, "_photocraft_downloading", False):
                self._photocraft_pending_hint_request = {
                    "hint_var": hint_var, "mode_var": mode_var, "mode_value": mode_value,
                    "source_clip": source_clip, "parent": parent,
                    "force_current_frame": force_current_frame,
                    "dedicated_path": dedicated_path, "first_frame_path": first_frame_path,
                    "psd_path": psd_path,
                }
                return
            self._photocraft_pending_hint_request = {
                "hint_var": hint_var, "mode_var": mode_var, "mode_value": mode_value,
                "source_clip": source_clip, "parent": parent,
                "force_current_frame": force_current_frame,
                "dedicated_path": dedicated_path, "first_frame_path": first_frame_path,
                "psd_path": psd_path,
            }
            self._append("[PhotoCraft] Companion app not found. Downloading the official app and CLI…", tag="dim")
            self._photocraft_download_official()
            return
        source_clip = str(source_clip or "").strip().strip('"')
        if not source_clip:
            input_var = getattr(self, "v_input", None)
            source_clip = str(input_var.get() if input_var is not None else "").strip().strip('"')
        if source_clip and (dedicated_path is None or first_frame_path is None or psd_path is None):
            paths = self._photocraft_artifact_paths(source_clip, "main")
            if dedicated_path is None:
                matched_hint = self._photocraft_find_matching_hint_png(
                    source_clip, preferred_path=(hint_var.get() if hint_var is not None else None))
                dedicated_path = matched_hint or paths["png"]
                if matched_hint is not None:
                    paired_psd = ROOT / "photocraft_psd" / f"{matched_hint.stem}.psd"
                    if paired_psd.is_file():
                        psd_path = psd_path or paired_psd
            first_frame_path = first_frame_path or paths["first_frame"]
            psd_path = psd_path or paths["psd"]

        # Without a source clip, retain a safe one-off path but still separate the files.
        if dedicated_path is None:
            stamp = time.strftime("%Y%m%d_%H%M%S") + f"_{time.time_ns() % 1_000_000:06d}"
            dedicated_path = ROOT / "hint_masks" / f"corridorkey_hint_{stamp}.png"
            psd_path = ROOT / "photocraft_psd" / f"corridorkey_hint_{stamp}.psd"
            first_frame_path = ROOT / "first_frames" / f"corridorkey_first_{stamp}.png"

        hint_png = Path(dedicated_path).expanduser().resolve()
        editable_psd = Path(psd_path or hint_png.with_suffix(".psd")).expanduser().resolve()
        first_png = Path(first_frame_path or (ROOT / "first_frames" / f"{hint_png.stem}_first.png")).expanduser().resolve()
        try:
            hint_png.parent.mkdir(parents=True, exist_ok=True)
            editable_psd.parent.mkdir(parents=True, exist_ok=True)
            first_png.parent.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            messagebox.showerror("PhotoCraft folders unavailable", str(exc), parent=parent)
            return

        # The first-frame PNG is a temporary seed, not a permanent dependency.
        # Create it only while this clip has neither an editable PSD nor a usable
        # render hint PNG. Once a PSD has been saved and flattened successfully,
        # the seed is deleted and must not be regenerated on the next edit.
        needs_first_frame_seed = not editable_psd.is_file() and not hint_png.is_file()
        try:
            if needs_first_frame_seed and source_clip:
                self._photocraft_create_first_frame_file(
                    source_clip, first_png,
                    overwrite=bool(force_current_frame and not editable_psd.is_file()))
            elif needs_first_frame_seed and not source_clip and not first_png.is_file():
                frame = getattr(self, "pv_base", None)
                if frame is None:
                    raise RuntimeError("Choose an input clip before creating its first frame.")
                frame.convert("RGBA").save(first_png, format="PNG", optimize=True)
        except Exception as exc:
            messagebox.showwarning("First frame was not created", str(exc), parent=parent)
            self._photocraft_set_status("FIRST FRAME EXTRACTION FAILED", RED)
            return

        # The per-clip frame-zero image is the initial source for this clip's
        # independent mask. Never seed a fresh clip mask from the shared/global
        # hint variable: that would silently make several clips depend on one file.
        # Once created, the clip-specific PSD is authoritative; its PNG is only
        # the flattened render hand-off updated after each PSD save.
        seed_source = hint_png if hint_png.is_file() else first_png

        if not editable_psd.is_file():
            try:
                seed_image = self._photocraft_read_still(seed_source)
                if seed_image is None:
                    raise RuntimeError(f"PhotoCraft could not decode the hint source: {seed_source}")
                temp_png = hint_png.with_name(hint_png.stem + ".seed.png")
                seed_image.convert("RGBA").save(temp_png, format="PNG", optimize=True)
                os.replace(temp_png, hint_png)
            except Exception as exc:
                messagebox.showerror(
                    "Could not prepare the PNG hint",
                    f"Could not prepare a render-ready PNG from {seed_source}:\n{exc}", parent=parent)
                return
        elif not hint_png.is_file():
            # Rebuild a missing render PNG straight from the durable PSD master.
            # The temporary first-frame seed may already have been deleted after a
            # previous successful save, so never depend on it for PSD recovery.
            try:
                hint_var.set(str(hint_png))
                if mode_var is getattr(self, "v_mode", None):
                    self._on_mode("First frame")
                elif mode_var is not None:
                    mode_var.set(mode_value)
            except Exception as exc:
                messagebox.showerror("Could not restore hint PNG", str(exc), parent=parent)
                return
            cli = self._photocraft_find_cli_executable()
            if cli is None:
                messagebox.showerror(
                    "PhotoCraft CLI not found",
                    "The saved PSD exists, but photocraft-cli.exe is required to rebuild its PNG hint. "
                    "Use the PhotoCraft hint action again to install the official portable package.", parent=parent)
                return
            # Reuse the PSD preparation worker's safe temp-and-replace conversion path.
            temp_png = hint_png.with_name(hint_png.stem + ".restoring.png")
            def restore_worker():
                error = ""
                try:
                    self._photocraft_cli_convert(str(cli), str(editable_psd), str(temp_png))
                    os.replace(temp_png, hint_png)
                except Exception as exc:
                    error = str(exc)
                    try:
                        temp_png.unlink()
                    except OSError:
                        pass
                try:
                    self.after(0, self._photocraft_psd_prepared, str(editable_psd), str(hint_png), error)
                except Exception:
                    pass
            psd_key = str(editable_psd.resolve())
            self._photocraft_hint_export_targets[psd_key] = str(hint_png)
            self._photocraft_first_frame_sources[psd_key] = str(first_png)
            threading.Thread(target=restore_worker, name="CorridorKeyPhotoCraftPNGRestore", daemon=True).start()
            return

        try:
            hint_var.set(str(hint_png))
            if mode_var is getattr(self, "v_mode", None):
                self._on_mode("First frame")
            elif mode_var is not None:
                mode_var.set(mode_value)
        except Exception as exc:
            messagebox.showerror("Could not update hint settings", str(exc), parent=parent)
            return

        psd_key = str(editable_psd.resolve())
        self._photocraft_hint_export_targets[psd_key] = str(hint_png)
        self._photocraft_first_frame_sources[psd_key] = str(first_png)
        open_log_lines = []
        if first_png.is_file():
            open_log_lines.append(
                f"[PhotoCraft] Temporary first-frame seed: {first_png.relative_to(ROOT)}")
        open_log_lines.extend((
            f"[PhotoCraft] Editable PSD: {editable_psd.relative_to(ROOT)}",
            f"[PhotoCraft] Render hint PNG: {hint_png.relative_to(ROOT)}. "
            "Save the PSD with Ctrl+S; the matching PNG is exported automatically, "
            "then the temporary first-frame seed is deleted.",
        ))
        self._append("\n".join(open_log_lines), tag="ok")
        if editable_psd.is_file():
            self._photocraft_launch(open_path=str(editable_psd))
        else:
            self._photocraft_prepare_psd_and_open(hint_png, editable_psd, hint_png)

    def _photocraft_watch_hint_file(self, image_path: str) -> None:
        """Watch every opened PSD tab independently and auto-export changed PSDs to PNG."""
        try:
            source = str(Path(image_path).expanduser().resolve())
            stat = Path(source).stat()
        except OSError:
            return
        png_target = self._photocraft_hint_export_targets.get(source)
        first_frame_source = getattr(self, "_photocraft_first_frame_sources", {}).get(source)
        watchers = getattr(self, "_photocraft_hint_watchers", None)
        if watchers is None:
            watchers = self._photocraft_hint_watchers = {}
        if source not in watchers:
            stamp = (int(stat.st_mtime_ns), int(stat.st_size))
            watchers[source] = {
                "source": source, "png": png_target,
                "first_frame": first_frame_source,
                "observed": stamp, "candidate": stamp,
                "stable_count": 0, "last_exported": stamp,
                "exporting": False, "last_logged": stamp,
            }
        else:
            watchers[source]["png"] = png_target or watchers[source].get("png")
            if first_frame_source:
                watchers[source]["first_frame"] = first_frame_source
        if self._photocraft_hint_watch_job is not None:
            try:
                self.after_cancel(self._photocraft_hint_watch_job)
            except Exception:
                pass
        self._photocraft_hint_watch_job = self.after(900, self._photocraft_poll_hint_watch)

    def _photocraft_delete_managed_first_frame(self, raw_path: str | Path, *, reason: str = "") -> bool:
        """Delete a temporary frame only when it is inside this project's first_frames folder."""
        first_frames_root = (ROOT / "first_frames").resolve()
        try:
            candidate = Path(raw_path).expanduser().resolve()
            candidate.relative_to(first_frames_root)
        except (OSError, ValueError, TypeError):
            self._append(
                f"[PhotoCraft] Kept first-frame file because its path is outside the managed first_frames folder: {raw_path}",
                tag="dim")
            return False
        try:
            if candidate.is_file():
                candidate.unlink()
                suffix = f" ({reason})" if reason else ""
                self._append(
                    f"[PhotoCraft] Temporary first frame removed{suffix}: {candidate.name}",
                    tag="ok")
                return True
        except OSError as exc:
            self._append(
                f"[PhotoCraft] Could not remove temporary first frame {candidate.name}: {exc}",
                tag="err")
        return False

    def _photocraft_cleanup_first_frame_after_export(self, source_psd: str) -> bool:
        """Delete this PSD's temporary first-frame seed after PNG export succeeds."""
        key = str(Path(source_psd).expanduser().resolve())
        raw_path = getattr(self, "_photocraft_first_frame_sources", {}).get(key)
        watcher_state = getattr(self, "_photocraft_hint_watchers", {}).get(key)
        if not raw_path and watcher_state:
            raw_path = watcher_state.get("first_frame")
        if not raw_path:
            return False
        deleted = self._photocraft_delete_managed_first_frame(
            raw_path, reason="after successful PSD→PNG export")
        if deleted:
            if watcher_state is not None:
                watcher_state["first_frame"] = None
            getattr(self, "_photocraft_first_frame_sources", {}).pop(key, None)
        return deleted

    def _photocraft_poll_hint_watch(self) -> None:
        """Debounce document saves, then flatten PSD to its matching PNG in a worker thread."""
        self._photocraft_hint_watch_job = None
        watchers = getattr(self, "_photocraft_hint_watchers", {})
        if not watchers:
            return
        for source, state in list(watchers.items()):
            try:
                stat = Path(source).stat()
                stamp = (int(stat.st_mtime_ns), int(stat.st_size))
            except OSError:
                continue
            if stamp != state.get("observed"):
                state["observed"] = stamp
                state["candidate"] = stamp
                state["stable_count"] = 0
            else:
                state["stable_count"] = int(state.get("stable_count", 0)) + 1
            if not state.get("png"):
                if stamp != state.get("last_logged"):
                    state["last_logged"] = stamp
                    self._append(
                        f"[PhotoCraft] Saved image updated: {Path(source).name}.", tag="ok")
                continue
            if (not state.get("exporting")
                    and stamp != state.get("last_exported")
                    and int(state.get("stable_count", 0)) >= 2):
                state["exporting"] = True
                state["export_stamp"] = stamp
                self._photocraft_start_png_export(state, stamp)
        self._photocraft_hint_watch_job = self.after(900, self._photocraft_poll_hint_watch)

    def _photocraft_start_png_export(self, state: dict, stamp: tuple[int, int]) -> None:
        """Flatten a stable PSD into a temporary PNG, validate it, then replace the hint."""
        cli = self._photocraft_find_cli_executable()
        source, target = state["source"], state["png"]
        if cli is None:
            state["exporting"] = False
            self._append(
                "[PhotoCraft] Auto-export failed: photocraft-cli.exe was not found beside PhotoCraft. "
                "Use Install / Update to repair the portable package.", tag="err")
            return
        temp_png = Path(target).with_name(
            Path(target).stem + f".exporting_{os.getpid()}_{time.time_ns() % 1_000_000}.png")
        self._append(
            f"[PhotoCraft] PSD saved: {Path(source).name}. Exporting replacement PNG…", tag="dim")

        def worker():
            error = ""
            try:
                self._photocraft_cli_convert(str(cli), source, str(temp_png))
                os.replace(temp_png, target)
            except Exception as exc:
                error = str(exc)
                try:
                    temp_png.unlink()
                except OSError:
                    pass
            try:
                self.after(0, self._photocraft_png_export_completed, source, target, stamp, error)
            except Exception:
                pass

        threading.Thread(target=worker, name="CorridorKeyPhotoCraftPNGExport", daemon=True).start()

    def _photocraft_png_export_completed(
        self, source: str, target: str, stamp: tuple[int, int], error: str = ""
    ) -> None:
        """Report a completed PSD-to-PNG export and let the watcher catch any newer save."""
        state = getattr(self, "_photocraft_hint_watchers", {}).get(source)
        if state is not None:
            state["exporting"] = False
            if not error:
                state["last_exported"] = stamp
        if error:
            self._append(
                f"[PhotoCraft] PNG auto-export failed for {Path(source).name}: {error}", tag="err")
            self._photocraft_set_status("PNG AUTO-EXPORT FAILED", RED)
            return
        self._append(
            f"[PhotoCraft] PNG updated: {Path(target).name}. This clip's next render will use the new matte.",
            tag="ok")
        # Delete the extracted frame only after the PSD has produced a valid PNG.
        # A failed export returns above and deliberately preserves the seed for recovery.
        self._photocraft_cleanup_first_frame_after_export(source)
        self._photocraft_set_status("PSD SAVED · PNG HINT UPDATED", ACCENT)

    def _photocraft_poll_window(self, deadline: float) -> None:
        proc = getattr(self, "_photocraft_process", None)
        if proc is None:
            return
        if proc.poll() is not None:
            self._photocraft_process = None
            self._photocraft_set_status("PHOTOCRAFT EXITED", RED)
            try:
                self.photocraft_placeholder.grid()
            except Exception:
                pass
            return
        if os.name == "nt":
            hwnd = self._photocraft_find_window_handle(proc.pid)
            if hwnd:
                self._photocraft_hwnd = hwnd
                if self._photocraft_set_embedded(True):
                    self._photocraft_set_status("PHOTOCRAFT EMBEDDED", ACCENT)
                    self.after(900, self._photocraft_monitor_process)
                    if self._photocraft_open_dialog_after_start:
                        self._photocraft_open_dialog_after_start = False
                        self.after(450, self._photocraft_open_image)
                    return
                self._photocraft_set_status("PHOTOCRAFT RUNNING · SEPARATE WINDOW", ORANGE)
                return
        if time.monotonic() >= deadline:
            self._photocraft_set_status("PHOTOCRAFT RUNNING · SEPARATE WINDOW", ORANGE)
            try:
                self.photocraft_placeholder_message.configure(
                    text="PhotoCraft is running in its own window. Use its native controls there; "
                         "the embedded host could not obtain its window handle on this system.")
                self.photocraft_placeholder.grid()
            except Exception:
                pass
            return
        self.after(200, self._photocraft_poll_window, deadline)

    def _photocraft_monitor_process(self) -> None:
        """Notice when the user closes PhotoCraft and restore the host placeholder."""
        proc = getattr(self, "_photocraft_process", None)
        if proc is None or getattr(self, "_closing", False):
            return
        if proc.poll() is not None:
            self._photocraft_process = None
            self._photocraft_hwnd = None
            self._photocraft_embedded = False
            self._photocraft_set_status("EDITOR CLOSED")
            try:
                self.b_photocraft_attach.configure(state="disabled", text="Detach")
                self.photocraft_placeholder.grid()
            except Exception:
                pass
            return
        try:
            self.after(900, self._photocraft_monitor_process)
        except Exception:
            pass

    def _photocraft_find_window_handle(self, process_id: int):
        """Find the visible top-level PhotoCraft window belonging to our process."""
        if os.name != "nt":
            return None
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        user32.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
        user32.GetWindowThreadProcessId.restype = wintypes.DWORD
        user32.IsWindowVisible.argtypes = [wintypes.HWND]
        user32.IsWindowVisible.restype = wintypes.BOOL
        user32.GetWindowTextLengthW.argtypes = [wintypes.HWND]
        user32.GetWindowTextLengthW.restype = ctypes.c_int
        user32.GetWindowTextW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
        user32.GetWindowTextW.restype = ctypes.c_int
        found = []
        enum_proc_type = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

        def callback(hwnd, _lparam):
            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            if pid.value != int(process_id) or not user32.IsWindowVisible(hwnd):
                return True
            title_length = user32.GetWindowTextLengthW(hwnd)
            title = ctypes.create_unicode_buffer(max(2, title_length + 2))
            user32.GetWindowTextW(hwnd, title, len(title))
            if "photocraft" in title.value.casefold() or not title.value.strip():
                handle_value = int(hwnd) if isinstance(hwnd, int) else int(hwnd.value or 0)
                if handle_value:
                    found.append(handle_value)
            return True

        callback_ref = enum_proc_type(callback)
        user32.EnumWindows(callback_ref, 0)
        return found[0] if found else None

    def _photocraft_set_embedded(self, embed: bool) -> bool:
        """Reparent PhotoCraft's native HWND into the CTk host on Windows."""
        if os.name != "nt" or not self._photocraft_hwnd:
            return False
        try:
            self.photocraft_host.update_idletasks()
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            hwnd = wintypes.HWND(int(self._photocraft_hwnd))
            get_style = getattr(user32, "GetWindowLongPtrW", user32.GetWindowLongW)
            set_style = getattr(user32, "SetWindowLongPtrW", user32.SetWindowLongW)
            get_style.argtypes = [wintypes.HWND, ctypes.c_int]
            get_style.restype = ctypes.c_ssize_t
            set_style.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_ssize_t]
            set_style.restype = ctypes.c_ssize_t
            user32.SetParent.argtypes = [wintypes.HWND, wintypes.HWND]
            user32.SetParent.restype = wintypes.HWND
            user32.SetWindowPos.argtypes = [wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int,
                                            ctypes.c_int, ctypes.c_int, wintypes.UINT]
            user32.SetWindowPos.restype = wintypes.BOOL
            user32.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
            user32.ShowWindow.restype = wintypes.BOOL
            if self._photocraft_original_style is None:
                self._photocraft_original_style = int(get_style(hwnd, -16))
            if embed:
                parent = wintypes.HWND(self.photocraft_host.winfo_id())
                style = (int(self._photocraft_original_style) & ~0x80000000) | 0x40000000 | 0x10000000 | 0x04000000 | 0x02000000
                width = max(1, int(self.photocraft_host.winfo_width()))
                height = max(1, int(self.photocraft_host.winfo_height()))
                set_style(hwnd, -16, style)
                ctypes.set_last_error(0)
                user32.SetParent(hwnd, parent)
                if ctypes.get_last_error():
                    raise ctypes.WinError(ctypes.get_last_error())
                user32.SetWindowPos(hwnd, None, 0, 0, width, height,
                                    0x0004 | 0x0010 | 0x0020 | 0x0040)
                user32.ShowWindow(hwnd, 5)
                self._photocraft_embedded = True
                self.b_photocraft_attach.configure(state="normal", text="Detach")
            else:
                style = int(self._photocraft_original_style)
                set_style(hwnd, -16, style)
                ctypes.set_last_error(0)
                user32.SetParent(hwnd, None)
                if ctypes.get_last_error():
                    raise ctypes.WinError(ctypes.get_last_error())
                user32.SetWindowPos(hwnd, None, 120, 100, 1280, 820,
                                    0x0004 | 0x0010 | 0x0020 | 0x0040)
                user32.ShowWindow(hwnd, 5)
                self._photocraft_embedded = False
                self.b_photocraft_attach.configure(state="normal", text="Re-embed")
            return True
        except Exception as exc:
            # If a DPI-awareness or parent-handle restriction blocks hosting, restore
            # the original top-level style so the native editor remains usable.
            try:
                if self._photocraft_original_style is not None:
                    user32 = ctypes.WinDLL("user32", use_last_error=True)
                    set_style = getattr(user32, "SetWindowLongPtrW", user32.SetWindowLongW)
                    set_style.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_ssize_t]
                    set_style.restype = ctypes.c_ssize_t
                    hwnd = wintypes.HWND(int(self._photocraft_hwnd))
                    set_style(hwnd, -16, int(self._photocraft_original_style))
                    ctypes.set_last_error(0)
                    user32.SetParent(hwnd, None)
                    user32.SetWindowPos(hwnd, None, 120, 100, 1280, 820, 0x0004 | 0x0010 | 0x0020 | 0x0040)
                    user32.ShowWindow(hwnd, 5)
            except Exception:
                pass
            self._photocraft_embedded = False
            try:
                self.b_photocraft_attach.configure(state="normal", text="Re-embed")
            except Exception:
                pass
            self._photocraft_set_status("WINDOW HOSTING UNAVAILABLE", ORANGE)
            try:
                self._photocraft_append_build_log(f"Window hosting note: {exc}\n")
            except Exception:
                pass
            return False

    def _photocraft_toggle_embedding(self) -> None:
        if not self._photocraft_hwnd:
            return
        self._photocraft_set_embedded(not self._photocraft_embedded)
        self._photocraft_focus_editor()

    def _photocraft_host_resized(self, _event=None) -> None:
        if not self._photocraft_embedded or not self._photocraft_hwnd or os.name != "nt":
            return
        if self._photocraft_resize_job is not None:
            try:
                self.after_cancel(self._photocraft_resize_job)
            except Exception:
                pass
        self._photocraft_resize_job = self.after(45, self._photocraft_resize_native_window)

    def _photocraft_resize_native_window(self) -> None:
        self._photocraft_resize_job = None
        if not self._photocraft_embedded or not self._photocraft_hwnd:
            return
        try:
            self.photocraft_host.update_idletasks()
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            user32.SetWindowPos.argtypes = [wintypes.HWND, wintypes.HWND, ctypes.c_int, ctypes.c_int,
                                            ctypes.c_int, ctypes.c_int, wintypes.UINT]
            user32.SetWindowPos.restype = wintypes.BOOL
            user32.SetWindowPos(
                wintypes.HWND(int(self._photocraft_hwnd)), None, 0, 0,
                max(1, int(self.photocraft_host.winfo_width())),
                max(1, int(self.photocraft_host.winfo_height())),
                0x0004 | 0x0010 | 0x0040)
        except Exception:
            pass

    def _photocraft_focus_editor(self) -> None:
        if not self._photocraft_hwnd or os.name != "nt":
            return
        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            hwnd = wintypes.HWND(int(self._photocraft_hwnd))
            user32.ShowWindow(hwnd, 5)
            user32.SetForegroundWindow(hwnd)
            user32.SetFocus(hwnd)
        except Exception:
            pass

    def _photocraft_open_image(self) -> None:
        """Focus PhotoCraft and invoke its native Open command (Ctrl+O)."""
        if self._photocraft_process is None or self._photocraft_process.poll() is not None:
            self._photocraft_open_dialog_after_start = True
            self._photocraft_launch()
            return
        if os.name != "nt" or not self._photocraft_hwnd:
            messagebox.showinfo(
                "Open an image",
                "Use File > Open inside the PhotoCraft window to choose an image.", parent=self)
            return
        self._photocraft_focus_editor()
        try:
            user32 = ctypes.WinDLL("user32", use_last_error=True)
            keybd_event = user32.keybd_event
            keybd_event.argtypes = [wintypes.BYTE, wintypes.BYTE, wintypes.DWORD, ctypes.c_size_t]
            keybd_event.restype = None
            keybd_event(0x11, 0, 0, 0)  # Ctrl down
            keybd_event(0x4F, 0, 0, 0)  # O down
            keybd_event(0x4F, 0, 2, 0)  # O up
            keybd_event(0x11, 0, 2, 0)  # Ctrl up
        except Exception as exc:
            self._photocraft_append_build_log(f"Could not send Ctrl+O: {exc}\n")

        """Queue Studio-only live pipeline graph and model activity monitor."""
        pg.grid_propagate(False)
        pg.grid_columnconfigure(0, weight=1, minsize=1)
