    @staticmethod
    def _make_omnitrix_hologram_glow(size: int = 272) -> Image.Image:
        """Create a restrained green holographic halo behind the Omnitrix dial."""
        image = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        glow = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        gd = ImageDraw.Draw(glow)
        pad = int(size * 0.12)
        gd.ellipse((pad, pad, size - pad, size - pad),
                   outline=(112, 255, 52, 48), width=max(2, size // 55))
        glow = glow.filter(ImageFilter.GaussianBlur(max(5, size // 24)))
        image = Image.alpha_composite(image, glow)
        draw = ImageDraw.Draw(image)
        draw.ellipse((pad + 5, pad + 5, size - pad - 5, size - pad - 5),
                     outline=(128, 255, 76, 62), width=max(1, size // 135))
        inner = int(size * 0.19)
        draw.ellipse((inner, inner, size - inner, size - inner),
                     outline=(92, 238, 56, 27), width=max(1, size // 170))
        # A few fine ticks imply a calibrated holographic interface, not a busy HUD.
        cx = cy = size / 2
        import math as _math
        radius = size * 0.43
        for angle in range(0, 360, 30):
            a = _math.radians(angle)
            x1, y1 = cx + _math.cos(a) * (radius - 4), cy + _math.sin(a) * (radius - 4)
            x2, y2 = cx + _math.cos(a) * radius, cy + _math.sin(a) * radius
            draw.line((x1, y1, x2, y2), fill=(140, 255, 100, 42), width=2)
        return image

    def _build_media_page_classic(self, pg) -> None:
        """Build the media pool; Ben 10 mode adds a dial with previous/next clip thumbnails."""
        pg.grid_columnconfigure(0, weight=1)
        self.media_view_mode = "List"
        has_omnitrix = self._active_interface_theme == "Ben 10 Omnitrix"

        if has_omnitrix:
            # A single Canvas owns the entire selector: left preview | Omnitrix | right preview.
            # Canvas image items have predictable pixel bounds and explicit z-order, avoiding
            # Tk/CTk child-widget clipping at either side of the circular dial.
            dial_stage = ctk.CTkFrame(pg, fg_color="transparent", corner_radius=0, height=250)
            dial_stage.grid(row=0, column=0, sticky="ew", pady=(0, 5))
            dial_stage.grid_propagate(False)
            dial_stage.grid_columnconfigure(0, weight=1)
            dial_stage.grid_rowconfigure(0, weight=1)
            self.omnitrix_panel = dial_stage
            dial_bg = resolve(BG)
            self.omnitrix_canvas = tk.Canvas(
                dial_stage, bg=dial_bg, bd=0, highlightthickness=0,
                relief="flat", takefocus=0)
            self.omnitrix_canvas.grid(row=0, column=0, sticky="nsew")
            geometry = self._omnitrix_thumbnail_geometry()

            def canvas_thumb_placeholder():
                w, h = geometry["thumb_width"], geometry["thumb_height"]
                base = Image.new("RGBA", (w, h), dial_bg)
                mask = Image.new("L", (w, h), 0)
                ImageDraw.Draw(mask).rounded_rectangle(
                    (0, 0, w - 1, h - 1), radius=9, fill=255)
                base.putalpha(mask)
                return ImageTk.PhotoImage(base, master=self.omnitrix_canvas)

            self.omnitrix_placeholder_thumb = canvas_thumb_placeholder()
            cx, cy = geometry["center_x"], geometry["center_y"]
            self.omnitrix_prev_thumb_button = self.omnitrix_canvas.create_image(
                geometry["left_x"], cy, image=self.omnitrix_placeholder_thumb,
                anchor="center", tags=("omnitrix_prev_thumb", "omnitrix_thumb"))
            self.omnitrix_next_thumb_button = self.omnitrix_canvas.create_image(
                geometry["right_x"], cy, image=self.omnitrix_placeholder_thumb,
                anchor="center", tags=("omnitrix_next_thumb", "omnitrix_thumb"))
            self._omnitrix_prepare_canvas_dial_frames()
            first_dial_photo = (self._omnitrix_canvas_frames[0]
                                if self._omnitrix_canvas_frames else self.omnitrix_placeholder_thumb)
            self._omnitrix_dial_item = self.omnitrix_canvas.create_image(
                cx, cy, image=first_dial_photo, anchor="center", tags=("omnitrix_dial",))
            # Full-size hit regions correspond exactly to the two visible thumbnails.
            self.omnitrix_canvas.tag_bind(
                self.omnitrix_prev_thumb_button, "<Button-1>",
                lambda _e: self._omnitrix_thumbnail_clicked(self.omnitrix_prev_thumb_button, -1))
            self.omnitrix_canvas.tag_bind(
                self.omnitrix_next_thumb_button, "<Button-1>",
                lambda _e: self._omnitrix_thumbnail_clicked(self.omnitrix_next_thumb_button, +1))
            self.omnitrix_canvas.tag_bind(
                self._omnitrix_dial_item, "<Button-1>", lambda _e: self._omnitrix_rotate_next())
            self.omnitrix_canvas.bind("<MouseWheel>", self._omnitrix_mousewheel, add="+")
            self.omnitrix_canvas.bind("<Button-4>", self._omnitrix_mousewheel, add="+")
            self.omnitrix_canvas.bind("<Button-5>", self._omnitrix_mousewheel, add="+")
            self.omnitrix_canvas.bind("<Configure>", self._omnitrix_stage_resized, add="+")
            self.omnitrix_button = self.omnitrix_canvas
            self.omnitrix_prev_button = None
            self.omnitrix_next_button = None
            self.omnitrix_count_label = None
            self.omnitrix_media_label = None
            self.omnitrix_canvas.tag_raise(self._omnitrix_dial_item)
            list_row, bar_row, queue_row = 2, 1, 3
        else:
            self.omnitrix_panel = None
            self.omnitrix_canvas = None
            self._omnitrix_dial_item = None
            self._omnitrix_canvas_frames = []
            self._omnitrix_prev_target_key = None
            self._omnitrix_next_target_key = None
            self.omnitrix_button = None
            self.omnitrix_prev_button = None
            self.omnitrix_next_button = None
            self.omnitrix_prev_thumb_button = None
            self.omnitrix_next_thumb_button = None
            self.omnitrix_prev_thumb_image = None
            self.omnitrix_next_thumb_image = None
            self.omnitrix_placeholder_thumb = None
            self.omnitrix_count_label = None
            self.omnitrix_media_label = None
            list_row, bar_row, queue_row = 1, 0, 2

        bar = ctk.CTkFrame(pg, fg_color="transparent")
        bar.grid(row=bar_row, column=0, sticky="ew", pady=(0, 8))
        self._pill(bar, "+ Files", self._media_import_files, 70).pack(side="left")
        self._pill(bar, "+ Folder", self._media_import_folder, 78).pack(side="left", padx=6)
        self._pill(bar, "Remove", self._media_remove, 74).pack(side="left")
        self._pill(bar, "Clear", self._media_clear, 62).pack(side="left", padx=6)

        card = ctk.CTkFrame(pg, fg_color=CARD, corner_radius=16, border_width=1, border_color=SEP)
        card.grid(row=list_row, column=0, sticky="nsew")
        card.grid_rowconfigure(0, weight=1)
        card.grid_columnconfigure(0, weight=1)
        self.media_list = ctk.CTkScrollableFrame(card, fg_color="transparent", corner_radius=14)
        self.media_list.grid(row=0, column=0, sticky="nsew", padx=4, pady=4)
        self.media_list.grid_columnconfigure(0, weight=1)
        self.l_media_empty = ctk.CTkLabel(
            self.media_list, text="No clips yet.\nImport files or a folder of videos.",
            font=self.f_small, text_color=SUBTLE, justify="center")
        self.l_media_empty.grid(row=0, column=0, pady=40)
        self._build_media_empty_state(card, columns=1)
        FadeButton(pg, text="Queue all clips", command=self._media_queue_all, height=38,
                   corner_radius=19, fg=ACCENT, hover=ACCENT_HOVER, text_color=ON_ACCENT,
                   font=self.f_body).grid(row=queue_row, column=0, sticky="ew", pady=(10, 0))
        # Batch and frame-limit controls remain in Setup; keep the Media page
        # focused on importing, reviewing and queueing clips.
        pg.grid_rowconfigure(list_row, weight=1)
        self._omnitrix_refresh_neighbor_thumbnails()

